-- ======================================================================
-- 20260913000100_phase01_profiles_and_audit.sql
-- ======================================================================

-- =============================================================================
-- Phase 01 — Authentication, RBAC and Security
--
-- Creates: profiles, audit_logs, the profile-creation trigger, and RLS.
--
-- Write-path rule (master plan §33):
--   The browser role gets SELECT on its own rows and nothing else.
--   Every INSERT / UPDATE / DELETE goes through a server action using the
--   service role, which checks ownership in code before writing.
--
-- Rationale: with the anon key the browser reaches PostgREST directly, so RLS
-- cannot distinguish the service layer from devtools. A column the client
-- never sends is a column the client cannot set.
--
-- Idempotent: safe to re-run.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- profiles
-- -----------------------------------------------------------------------------

create table if not exists public.profiles (
  id               uuid primary key references auth.users (id) on delete cascade,
  email            text,
  full_name        text,
  avatar_url       text,
  role             text        not null default 'user',
  status           text        not null default 'active',
  -- Asia/Manila is assumed by phases 02, 03, 06, 07, 08, 09 and 12 for
  -- transaction dates, due-date comparison, analytics month boundaries,
  -- forecast dates, usage periods and relative date parsing. One
  -- authoritative value beats seven hardcoded strings.
  timezone         text        not null default 'Asia/Manila',
  default_currency text        not null default 'PHP',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

comment on table public.profiles is
  'Application-level user record. 1:1 with auth.users. role and status have no client-writable path.';

-- Constraints added defensively: Postgres has no ADD CONSTRAINT IF NOT EXISTS.
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_role_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_role_check check (role in ('user', 'admin'));
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_status_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_status_check
      check (status in ('active', 'suspended', 'disabled'));
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_currency_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_currency_check check (char_length(default_currency) = 3);
  end if;
end $$;

-- RLS policies filter on id; the primary key index already covers it.
-- Partial index for the admin lookup, which is rare and highly selective.
create index if not exists profiles_role_idx
  on public.profiles (role) where role = 'admin';

create index if not exists profiles_status_idx
  on public.profiles (status) where status <> 'active';

-- -----------------------------------------------------------------------------
-- audit_logs
--
-- Created with the FULL shape Phase 02 needs, not a reduced one. Phase 01 only
-- populates the auth-event columns and leaves entity/diff columns null — but
-- creating the narrow shape now would mean an ALTER on Phase 02's first day.
-- -----------------------------------------------------------------------------

create table if not exists public.audit_logs (
  id             uuid        primary key default gen_random_uuid(),
  actor_user_id  uuid        references auth.users (id) on delete set null,
  target_user_id uuid        references auth.users (id) on delete set null,
  entity_type    text,
  entity_id      uuid,
  event_type     text        not null,
  before_data    jsonb,
  after_data     jsonb,
  metadata       jsonb       not null default '{}'::jsonb,
  created_at     timestamptz not null default now()
);

comment on table public.audit_logs is
  'Append-only. No UPDATE or DELETE policy exists for any role, including the user who owns the row.';

create index if not exists audit_logs_target_created_idx
  on public.audit_logs (target_user_id, created_at desc);

create index if not exists audit_logs_entity_idx
  on public.audit_logs (entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- updated_at maintenance
-- -----------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Profile creation on signup
--
-- A database trigger rather than application code, so email/password and
-- Google OAuth produce identical results. Application-side creation would have
-- to be duplicated per provider and would silently skip if a signup path were
-- added later.
--
-- SECURITY DEFINER because it writes to a table the signing-up user has no
-- INSERT privilege on. search_path is pinned to empty to prevent search-path
-- hijacking — mandatory for any SECURITY DEFINER function.
-- -----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name, avatar_url, role, status)
  values (
    new.id,
    new.email,
    -- Google returns full_name or name; email signup may send full_name.
    coalesce(
      new.raw_user_meta_data ->> 'full_name',
      new.raw_user_meta_data ->> 'name'
    ),
    coalesce(
      new.raw_user_meta_data ->> 'avatar_url',
      new.raw_user_meta_data ->> 'picture'
    ),
    -- Never read role from user metadata. OAuth metadata is attacker-adjacent
    -- and sign-up payloads are client-controlled.
    'user',
    'active'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Backfill any users that predate this migration.
insert into public.profiles (id, email, full_name, avatar_url, role, status)
select
  u.id,
  u.email,
  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
  coalesce(u.raw_user_meta_data ->> 'avatar_url', u.raw_user_meta_data ->> 'picture'),
  'user',
  'active'
from auth.users u
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------

alter table public.profiles   enable row level security;
alter table public.profiles   force  row level security;
alter table public.audit_logs enable row level security;
alter table public.audit_logs force  row level security;

-- profiles: read own row only.
-- auth.uid() is wrapped in a subselect so it is evaluated once per query
-- rather than once per row.
drop policy if exists profiles_select_own on public.profiles;
create policy profiles_select_own
  on public.profiles
  for select
  to authenticated
  using (id = (select auth.uid()));

-- No INSERT / UPDATE / DELETE policy for `authenticated`, deliberately.
-- Inserts come from the trigger (SECURITY DEFINER); updates come from server
-- actions using the service role, which bypasses RLS and is never exposed to
-- the browser.

-- audit_logs: read own history. Append-only for everyone.
drop policy if exists audit_logs_select_own on public.audit_logs;
create policy audit_logs_select_own
  on public.audit_logs
  for select
  to authenticated
  using (target_user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Least privilege
-- -----------------------------------------------------------------------------

revoke all on public.profiles   from anon, authenticated;
revoke all on public.audit_logs from anon, authenticated;

grant select on public.profiles   to authenticated;
grant select on public.audit_logs to authenticated;

-- anon gets nothing: an unauthenticated visitor has no rows to see.


-- ======================================================================
-- 20260913000200_phase02_financial_core.sql
-- ======================================================================

-- =============================================================================
-- Phase 02 — Financial Core
--
-- accounts, categories, transactions, tags, transaction_tags.
--
-- Two rules this schema enforces rather than trusts:
--
--   1. amount is ALWAYS positive. Direction comes from transaction type and
--      account role (see lib/finance/balance.ts), never from a stored sign.
--   2. accounts.opening_balance is input-only. The authoritative opening
--      amount is an opening_balance TRANSACTION. Summing both would make every
--      account wrong by exactly its opening amount, in a way that reconciles
--      against nothing.
--
-- Write-path rule (master plan §33): browser gets SELECT on own rows; all
-- mutations go through server actions using the service role.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- accounts
-- -----------------------------------------------------------------------------

create table if not exists public.accounts (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  name             text not null,
  type             text not null,
  nature           text not null,
  currency_code    text not null default 'PHP',
  -- Input-only. Never summed. See header.
  opening_balance  numeric(18, 2) not null default 0,
  -- Cache. Always recomputable from transactions via recalculate_account_balance().
  current_balance  numeric(18, 2) not null default 0,
  institution_name text,
  is_active        boolean not null default true,
  is_archived      boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

comment on column public.accounts.opening_balance is
  'What the user typed when creating the account. Display and audit only — NEVER summed into a balance. The opening_balance transaction is authoritative.';
comment on column public.accounts.current_balance is
  'Cached. Derived from transactions; recomputable at any time. Never client-writable.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'accounts_type_check') then
    alter table public.accounts add constraint accounts_type_check
      check (type in ('cash','bank','gcash','maya','paypal','credit_card','loan','investment','other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_nature_check') then
    alter table public.accounts add constraint accounts_nature_check
      check (nature in ('asset','liability'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_currency_check') then
    alter table public.accounts add constraint accounts_currency_check
      check (char_length(currency_code) = 3);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_name_check') then
    alter table public.accounts add constraint accounts_name_check
      check (char_length(btrim(name)) between 1 and 80);
  end if;
end $$;

create index if not exists accounts_user_idx on public.accounts (user_id);
create index if not exists accounts_user_active_idx
  on public.accounts (user_id) where is_archived = false;

drop trigger if exists accounts_set_updated_at on public.accounts;
create trigger accounts_set_updated_at before update on public.accounts
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- categories
--
-- System categories have user_id null and are readable by everyone.
-- -----------------------------------------------------------------------------

create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references auth.users (id) on delete cascade,
  name        text not null,
  type        text not null,
  icon        text,
  is_system   boolean not null default false,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'categories_type_check') then
    alter table public.categories add constraint categories_type_check
      check (type in ('income','expense','both'));
  end if;
  -- A system category must have no owner; a user category must have one.
  if not exists (select 1 from pg_constraint where conname = 'categories_ownership_check') then
    alter table public.categories add constraint categories_ownership_check
      check ((is_system and user_id is null) or (not is_system and user_id is not null));
  end if;
end $$;

create index if not exists categories_user_idx on public.categories (user_id);
create unique index if not exists categories_system_name_idx
  on public.categories (lower(name), type) where is_system;

drop trigger if exists categories_set_updated_at on public.categories;
create trigger categories_set_updated_at before update on public.categories
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- transactions
-- -----------------------------------------------------------------------------

create table if not exists public.transactions (
  id                       uuid primary key default gen_random_uuid(),
  user_id                  uuid not null references auth.users (id) on delete cascade,
  type                     text not null,
  direction                text,
  amount                   numeric(18, 2) not null,
  currency_code            text not null default 'PHP',
  transaction_date         date not null,
  source_account_id        uuid references public.accounts (id) on delete restrict,
  destination_account_id   uuid references public.accounts (id) on delete restrict,
  category_id              uuid references public.categories (id) on delete set null,
  merchant_name            text,
  description              text,
  notes                    text,
  refund_of_transaction_id uuid references public.transactions (id) on delete set null,
  transfer_group_id        uuid,
  status                   text not null default 'confirmed',
  void_reason              text,
  is_archived              boolean not null default false,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

comment on column public.transactions.amount is
  'ALWAYS positive. Direction is derived from type and account role — see lib/finance/balance.ts §34.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'transactions_amount_check') then
    alter table public.transactions add constraint transactions_amount_check
      check (amount > 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_type_check') then
    alter table public.transactions add constraint transactions_type_check
      check (type in ('income','expense','transfer','refund','adjustment','opening_balance'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_status_check') then
    alter table public.transactions add constraint transactions_status_check
      check (status in ('confirmed','voided'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_direction_check') then
    alter table public.transactions add constraint transactions_direction_check
      check (direction is null or direction in ('increase','decrease'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_currency_check') then
    alter table public.transactions add constraint transactions_currency_check
      check (char_length(currency_code) = 3);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_distinct_accounts_check') then
    alter table public.transactions add constraint transactions_distinct_accounts_check
      check (source_account_id is null
             or destination_account_id is null
             or source_account_id <> destination_account_id);
  end if;

  -- §34a encoded in the database, so a service bug cannot write an
  -- unbalanceable row. These are the shapes lib/finance/balance.ts assumes.
  if not exists (select 1 from pg_constraint where conname = 'transactions_shape_check') then
    alter table public.transactions add constraint transactions_shape_check check (
      case type
        when 'income'          then destination_account_id is not null and source_account_id is null
        when 'refund'          then destination_account_id is not null and source_account_id is null
        when 'opening_balance' then destination_account_id is not null and source_account_id is null
        when 'expense'         then source_account_id is not null and destination_account_id is null
        when 'adjustment'      then source_account_id is not null and destination_account_id is null
                                    and direction is not null
        when 'transfer'        then source_account_id is not null and destination_account_id is not null
        else false
      end
    );
  end if;
end $$;

create index if not exists transactions_user_date_idx
  on public.transactions (user_id, transaction_date desc);
create index if not exists transactions_user_type_idx
  on public.transactions (user_id, type);
create index if not exists transactions_user_category_idx
  on public.transactions (user_id, category_id);
create index if not exists transactions_source_idx
  on public.transactions (source_account_id) where source_account_id is not null;
create index if not exists transactions_destination_idx
  on public.transactions (destination_account_id) where destination_account_id is not null;
-- Partial: analytics and balances read confirmed rows almost exclusively.
create index if not exists transactions_confirmed_idx
  on public.transactions (user_id, transaction_date desc) where status = 'confirmed';

drop trigger if exists transactions_set_updated_at on public.transactions;
create trigger transactions_set_updated_at before update on public.transactions
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- tags
-- -----------------------------------------------------------------------------

create table if not exists public.tags (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  name       text not null,
  created_at timestamptz not null default now()
);

create unique index if not exists tags_user_name_idx on public.tags (user_id, lower(name));

create table if not exists public.transaction_tags (
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  tag_id         uuid not null references public.tags (id) on delete cascade,
  user_id        uuid not null references auth.users (id) on delete cascade,
  primary key (transaction_id, tag_id)
);

create index if not exists transaction_tags_tag_idx on public.transaction_tags (tag_id);

-- -----------------------------------------------------------------------------
-- Balance derivation
--
-- The SQL mirror of lib/finance/balance.ts §34. Both must agree; the tests in
-- lib/finance/balance.test.ts define the contract.
-- -----------------------------------------------------------------------------

create or replace function public.recalculate_account_balance(p_account_id uuid)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nature  text;
  v_balance numeric(18, 2);
begin
  select nature into v_nature from public.accounts where id = p_account_id;
  if v_nature is null then
    raise exception 'No account %', p_account_id;
  end if;

  select coalesce(sum(
    case
      -- as SOURCE
      when t.source_account_id = p_account_id then
        case t.type
          when 'expense'    then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'transfer'   then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'adjustment' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      -- as DESTINATION
      when t.destination_account_id = p_account_id then
        case t.type
          when 'income'          then case when v_nature = 'asset' then t.amount else 0 end
          when 'refund'          then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'transfer'        then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'opening_balance' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      else 0
    end
  ), 0)
  into v_balance
  from public.transactions t
  where t.status = 'confirmed'
    and (t.source_account_id = p_account_id or t.destination_account_id = p_account_id);

  update public.accounts set current_balance = v_balance where id = p_account_id;
  return v_balance;
end;
$$;

comment on function public.recalculate_account_balance(uuid) is
  'Derives the authoritative balance from confirmed transactions only. accounts.opening_balance is deliberately excluded.';

-- -----------------------------------------------------------------------------
-- Seed system categories (§13, §14)
-- -----------------------------------------------------------------------------

insert into public.categories (user_id, name, type, is_system)
select null, name, 'expense', true
from (values
  ('Food'),('Transportation'),('Housing'),('Utilities'),('Loans'),('Education'),
  ('Health'),('Shopping'),('Entertainment'),('Subscriptions'),('Fitness'),
  ('Car'),('Business'),('Technology'),('Travel'),('Other')
) as t(name)
on conflict do nothing;

insert into public.categories (user_id, name, type, is_system)
select null, name, 'income', true
from (values
  ('Salary'),('Freelance'),('Business Income'),('Allowance'),
  ('Refund'),('Interest'),('Investment Income'),('Other Income')
) as t(name)
on conflict do nothing;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------

alter table public.accounts         enable row level security;
alter table public.accounts         force  row level security;
alter table public.categories       enable row level security;
alter table public.categories       force  row level security;
alter table public.transactions     enable row level security;
alter table public.transactions     force  row level security;
alter table public.tags             enable row level security;
alter table public.tags             force  row level security;
alter table public.transaction_tags enable row level security;
alter table public.transaction_tags force  row level security;

drop policy if exists accounts_select_own on public.accounts;
create policy accounts_select_own on public.accounts
  for select to authenticated using (user_id = (select auth.uid()));

-- System categories are shared; user categories are private.
drop policy if exists categories_select on public.categories;
create policy categories_select on public.categories
  for select to authenticated
  using (is_system or user_id = (select auth.uid()));

drop policy if exists transactions_select_own on public.transactions;
create policy transactions_select_own on public.transactions
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists tags_select_own on public.tags;
create policy tags_select_own on public.tags
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists transaction_tags_select_own on public.transaction_tags;
create policy transaction_tags_select_own on public.transaction_tags
  for select to authenticated using (user_id = (select auth.uid()));

-- No INSERT / UPDATE / DELETE policies for `authenticated`, deliberately.

revoke all on public.accounts, public.categories, public.transactions,
              public.tags, public.transaction_tags
  from anon, authenticated;

grant select on public.accounts, public.categories, public.transactions,
                public.tags, public.transaction_tags
  to authenticated;


-- ======================================================================
-- 20260913000300_phase02_transaction_rpc.sql
-- ======================================================================

-- =============================================================================
-- Phase 02 — atomic transaction operations (§37, §64)
--
-- Creating, editing and voiding a transaction each touch a row plus one or two
-- cached balances. Done as separate statements from application code, a crash
-- or a concurrent request between them leaves a balance that disagrees with the
-- ledger — and nothing surfaces it until someone reconciles by hand.
--
-- So each operation is one SQL function: one transaction, all or nothing.
--
-- Ownership is verified INSIDE each function against p_user_id, which callers
-- resolve from the session. These are SECURITY DEFINER, so they bypass RLS —
-- the ownership check here is the only thing standing between a caller and
-- another user's accounts.
-- =============================================================================

-- Shared: assert every referenced account belongs to the user and matches the
-- transaction currency. Raises rather than returning, so a caller cannot
-- accidentally ignore the result.
create or replace function public.assert_account_access(
  p_user_id       uuid,
  p_account_id    uuid,
  p_currency_code text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner    uuid;
  v_currency text;
  v_archived boolean;
begin
  if p_account_id is null then
    return;
  end if;

  select user_id, currency_code, is_archived
    into v_owner, v_currency, v_archived
  from public.accounts
  where id = p_account_id;

  if v_owner is null then
    raise exception 'ACCOUNT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_owner <> p_user_id then
    -- Same error as not-found on purpose: a distinguishable "forbidden"
    -- confirms the account exists, which is an enumeration oracle.
    raise exception 'ACCOUNT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_archived then
    raise exception 'ACCOUNT_ARCHIVED' using errcode = 'P0001';
  end if;
  if v_currency <> p_currency_code then
    -- HelloPera never converts (master plan §11).
    raise exception 'CURRENCY_MISMATCH' using errcode = 'P0001';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- create_transaction
-- -----------------------------------------------------------------------------

create or replace function public.create_transaction(
  p_user_id              uuid,
  p_type                 text,
  p_amount               numeric,
  p_currency_code        text,
  p_transaction_date     date,
  p_source_account_id    uuid   default null,
  p_destination_account_id uuid default null,
  p_category_id          uuid   default null,
  p_direction            text   default null,
  p_merchant_name        text   default null,
  p_description          text   default null,
  p_notes                text   default null,
  p_refund_of            uuid   default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;

  perform public.assert_account_access(p_user_id, p_source_account_id, p_currency_code);
  perform public.assert_account_access(p_user_id, p_destination_account_id, p_currency_code);

  if p_category_id is not null then
    if not exists (
      select 1 from public.categories
      where id = p_category_id and (is_system or user_id = p_user_id)
    ) then
      raise exception 'CATEGORY_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  -- Lock the affected accounts in a stable order (by id) so two concurrent
  -- writes touching the same pair cannot deadlock by grabbing them opposite
  -- ways round.
  perform 1 from public.accounts
  where id in (p_source_account_id, p_destination_account_id)
  order by id
  for update;

  insert into public.transactions (
    user_id, type, direction, amount, currency_code, transaction_date,
    source_account_id, destination_account_id, category_id,
    merchant_name, description, notes, refund_of_transaction_id, status
  ) values (
    p_user_id, p_type, p_direction, p_amount, p_currency_code, p_transaction_date,
    p_source_account_id, p_destination_account_id, p_category_id,
    nullif(btrim(coalesce(p_merchant_name, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    p_refund_of, 'confirmed'
  )
  returning id into v_id;

  -- Recompute from the ledger rather than incrementing the cache: an
  -- increment that runs twice is undetectable, a recompute is idempotent.
  if p_source_account_id is not null then
    perform public.recalculate_account_balance(p_source_account_id);
  end if;
  if p_destination_account_id is not null then
    perform public.recalculate_account_balance(p_destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'transaction', v_id, 'transaction_created',
     jsonb_build_object('type', p_type, 'amount', p_amount, 'currency', p_currency_code));

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- void_transaction
--
-- Voiding, never deleting (§32). The row stays visible in history and audit;
-- it simply stops affecting balances.
-- -----------------------------------------------------------------------------

create or replace function public.void_transaction(
  p_user_id uuid,
  p_id      uuid,
  p_reason  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tx public.transactions%rowtype;
begin
  select * into v_tx from public.transactions
  where id = p_id and user_id = p_user_id
  for update;

  if v_tx.id is null then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx.status = 'voided' then
    -- Idempotent: a double submit must not produce a second audit entry.
    return;
  end if;

  update public.transactions
  set status = 'voided',
      void_reason = nullif(btrim(coalesce(p_reason, '')), '')
  where id = p_id;

  if v_tx.source_account_id is not null then
    perform public.recalculate_account_balance(v_tx.source_account_id);
  end if;
  if v_tx.destination_account_id is not null then
    perform public.recalculate_account_balance(v_tx.destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type,
     before_data, after_data, metadata)
  values
    (p_user_id, p_user_id, 'transaction', p_id, 'transaction_voided',
     jsonb_build_object('status', 'confirmed', 'amount', v_tx.amount),
     jsonb_build_object('status', 'voided'),
     jsonb_build_object('reason', coalesce(p_reason, '')));
end;
$$;

-- -----------------------------------------------------------------------------
-- create_account
--
-- The account and its opening_balance transaction are created together.
-- Separately, a crash between them leaves an account whose stated opening
-- balance has no ledger entry behind it.
-- -----------------------------------------------------------------------------

create or replace function public.create_account(
  p_user_id          uuid,
  p_name             text,
  p_type             text,
  p_nature           text,
  p_currency_code    text,
  p_opening_balance  numeric default 0,
  p_institution_name text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.accounts
    (user_id, name, type, nature, currency_code, opening_balance, institution_name)
  values
    (p_user_id, btrim(p_name), p_type, p_nature, upper(p_currency_code),
     coalesce(p_opening_balance, 0),
     nullif(btrim(coalesce(p_institution_name, '')), ''))
  returning id into v_id;

  -- Only when non-zero: an opening_balance row of 0 is noise in the ledger.
  if coalesce(p_opening_balance, 0) <> 0 then
    insert into public.transactions
      (user_id, type, direction, amount, currency_code, transaction_date,
       destination_account_id, status, description)
    values
      (p_user_id, 'opening_balance',
       case when p_opening_balance < 0 then 'decrease' else 'increase' end,
       abs(p_opening_balance), upper(p_currency_code), current_date,
       v_id, 'confirmed', 'Opening balance');
  end if;

  perform public.recalculate_account_balance(v_id);

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'account', v_id, 'account_created',
     jsonb_build_object('name', p_name, 'type', p_type, 'nature', p_nature));

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Integrity check (§36, and Phase 14 §64)
-- -----------------------------------------------------------------------------

create or replace function public.check_balance_integrity(p_user_id uuid)
returns table (account_id uuid, account_name text, cached numeric, derived numeric)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  select a.id, a.name, a.current_balance,
         public.recalculate_account_balance(a.id)
  from public.accounts a
  where a.user_id = p_user_id;
end;
$$;

comment on function public.check_balance_integrity(uuid) is
  'Reports cached vs derived balance per account. Recalculating repairs as it reads, so run it to both detect and fix drift.';

-- Callable by the service role only. These bypass RLS by design.
revoke all on function public.create_transaction from anon, authenticated;
revoke all on function public.void_transaction   from anon, authenticated;
revoke all on function public.create_account     from anon, authenticated;
revoke all on function public.assert_account_access from anon, authenticated;
revoke all on function public.recalculate_account_balance from anon, authenticated;
revoke all on function public.check_balance_integrity from anon, authenticated;


-- ======================================================================
-- 20260913000400_lock_schema_migrations.sql
-- ======================================================================

-- =============================================================================
-- Lock down schema_migrations.
--
-- The migration runner created this table with a plain CREATE TABLE, so
-- Supabase's default grants applied and anon/authenticated received ALL
-- privileges — including TRUNCATE. It holds no user data, but an anonymous
-- visitor being able to erase migration history is exactly the kind of default
-- that should never survive a verification pass.
--
-- Caught by supabase/VERIFY-RLS.sql, which is why that file checks grants and
-- not just policies.
-- =============================================================================

alter table if exists public.schema_migrations enable row level security;
alter table if exists public.schema_migrations force  row level security;

revoke all on public.schema_migrations from anon, authenticated;

-- No policies at all: this table is for the migration runner, which connects
-- as the database owner and is unaffected by RLS grants to PostgREST roles.


-- ======================================================================
-- 20260913000500_reject_income_to_liability.sql
-- ======================================================================

-- =============================================================================
-- Reject income into a liability account.
--
-- Found by the Phase 02 end-to-end test. The shape CHECK only requires income
-- to have a destination; it cannot verify that account's NATURE, because a
-- CHECK constraint may not run a subquery.
--
-- So income into a credit card was accepted, and then had zero balance effect
-- (lib/finance/balance.ts §34: income only applies to assets). The user records
-- income, no balance moves, and nothing reports an error — the worst shape of
-- bug in a ledger, because it is silent.
--
-- Enforced in the RPC, which is the only write path.
-- =============================================================================

create or replace function public.assert_income_destination(
  p_type       text,
  p_account_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nature text;
begin
  if p_type <> 'income' or p_account_id is null then
    return;
  end if;

  select nature into v_nature from public.accounts where id = p_account_id;

  if v_nature <> 'asset' then
    -- Money arriving on a credit card is a refund (reduces debt) or a
    -- transfer, not income. Both are supported; income is not.
    raise exception 'INCOME_REQUIRES_ASSET' using errcode = 'P0001';
  end if;
end;
$$;

revoke all on function public.assert_income_destination from anon, authenticated;

-- Re-create create_transaction with the extra assertion. Body is otherwise
-- unchanged from 20260913000300.
create or replace function public.create_transaction(
  p_user_id                uuid,
  p_type                   text,
  p_amount                 numeric,
  p_currency_code          text,
  p_transaction_date       date,
  p_source_account_id      uuid default null,
  p_destination_account_id uuid default null,
  p_category_id            uuid default null,
  p_direction              text default null,
  p_merchant_name          text default null,
  p_description            text default null,
  p_notes                  text default null,
  p_refund_of              uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;

  perform public.assert_account_access(p_user_id, p_source_account_id, p_currency_code);
  perform public.assert_account_access(p_user_id, p_destination_account_id, p_currency_code);
  perform public.assert_income_destination(p_type, p_destination_account_id);

  if p_category_id is not null then
    if not exists (
      select 1 from public.categories
      where id = p_category_id and (is_system or user_id = p_user_id)
    ) then
      raise exception 'CATEGORY_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  perform 1 from public.accounts
  where id in (p_source_account_id, p_destination_account_id)
  order by id
  for update;

  insert into public.transactions (
    user_id, type, direction, amount, currency_code, transaction_date,
    source_account_id, destination_account_id, category_id,
    merchant_name, description, notes, refund_of_transaction_id, status
  ) values (
    p_user_id, p_type, p_direction, p_amount, p_currency_code, p_transaction_date,
    p_source_account_id, p_destination_account_id, p_category_id,
    nullif(btrim(coalesce(p_merchant_name, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    p_refund_of, 'confirmed'
  )
  returning id into v_id;

  if p_source_account_id is not null then
    perform public.recalculate_account_balance(p_source_account_id);
  end if;
  if p_destination_account_id is not null then
    perform public.recalculate_account_balance(p_destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'transaction', v_id, 'transaction_created',
     jsonb_build_object('type', p_type, 'amount', p_amount, 'currency', p_currency_code));

  return v_id;
end;
$$;

revoke all on function public.create_transaction from anon, authenticated;


-- ======================================================================
-- 20260913000600_phase03_obligations.sql
-- ======================================================================

-- =============================================================================
-- Phase 03 — Bills, Receivables and Expected Income
--
-- CORE MODELLING RULE (§4):
--   An obligation is not a transaction. A bill is not an expense; a receivable
--   is not income; expected income is not income. Only actual money movement
--   creates a transaction. Link tables record which transaction settled which
--   obligation, and by how much.
--
-- STATUS (§9, §38):
--   Persisted:  open | partially_paid | paid | cancelled   — lifecycle
--   Derived:    upcoming | due_soon | due_today | overdue   — time
--
--   Time-based states are computed at read time from due_date and the
--   remaining amount. Storing them would mean a daily job whose only purpose
--   is refreshing a label, and a label that is silently wrong between runs.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- bills
-- -----------------------------------------------------------------------------

create table if not exists public.bills (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  provider_name text not null,
  description   text,
  category_id   uuid references public.categories (id) on delete set null,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  due_date      date not null,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on column public.bills.status is
  'Lifecycle only: open | partially_paid | paid | cancelled. Time states (due_soon, overdue) are derived at read time.';

-- -----------------------------------------------------------------------------
-- receivables
-- -----------------------------------------------------------------------------

create table if not exists public.receivables (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  party_name    text not null,
  description   text,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  due_date      date,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- expected_income
--
-- Distinct from receivables (§30): a receivable is a defined debt someone owes
-- you; expected income is anticipated money that nobody owes yet — a salary,
-- a stipend, a likely freelance payment.
-- -----------------------------------------------------------------------------

create table if not exists public.expected_income (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  source_name   text not null,
  description   text,
  category_id   uuid references public.categories (id) on delete set null,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  expected_date date not null,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['bills', 'receivables', 'expected_income'] loop
    -- One persisted lifecycle vocabulary across all three, so the allocation
    -- function can stay polymorphic.
    if not exists (select 1 from pg_constraint where conname = t || '_status_check') then
      execute format(
        'alter table public.%I add constraint %I check (status in (%L,%L,%L,%L))',
        t, t || '_status_check', 'open', 'partially_paid', 'paid', 'cancelled');
    end if;
    if not exists (select 1 from pg_constraint where conname = t || '_amount_check') then
      execute format('alter table public.%I add constraint %I check (amount > 0)',
                     t, t || '_amount_check');
    end if;
    if not exists (select 1 from pg_constraint where conname = t || '_currency_check') then
      execute format('alter table public.%I add constraint %I check (char_length(currency_code) = 3)',
                     t, t || '_currency_check');
    end if;
    execute format('drop trigger if exists %I on public.%I', t || '_set_updated_at', t);
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
      t || '_set_updated_at', t);
  end loop;
end $$;

create index if not exists bills_user_due_idx on public.bills (user_id, due_date);
create index if not exists bills_open_idx on public.bills (user_id, due_date)
  where status in ('open', 'partially_paid');
create index if not exists receivables_user_due_idx on public.receivables (user_id, due_date);
create index if not exists receivables_open_idx on public.receivables (user_id, due_date)
  where status in ('open', 'partially_paid');
create index if not exists expected_income_user_date_idx
  on public.expected_income (user_id, expected_date);

-- -----------------------------------------------------------------------------
-- Link tables
--
-- amount_applied on both sides (§36) so one transaction can settle several
-- obligations and one obligation can take several transactions. Retrofitting
-- this shape later is painful, so it is here from the start even though the
-- MVP flow is one-to-one.
-- -----------------------------------------------------------------------------

create table if not exists public.bill_payments (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  bill_id        uuid not null references public.bills (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete restrict,
  amount_applied numeric(18, 2) not null check (amount_applied > 0),
  created_at     timestamptz not null default now()
);

create table if not exists public.receivable_payments (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  receivable_id  uuid not null references public.receivables (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete restrict,
  amount_applied numeric(18, 2) not null check (amount_applied > 0),
  created_at     timestamptz not null default now()
);

create table if not exists public.expected_income_receipts (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  expected_income_id uuid not null references public.expected_income (id) on delete cascade,
  transaction_id     uuid not null references public.transactions (id) on delete restrict,
  amount_applied     numeric(18, 2) not null check (amount_applied > 0),
  created_at         timestamptz not null default now()
);

create index if not exists bill_payments_bill_idx on public.bill_payments (bill_id);
create index if not exists bill_payments_tx_idx on public.bill_payments (transaction_id);
create index if not exists receivable_payments_recv_idx on public.receivable_payments (receivable_id);
create index if not exists receivable_payments_tx_idx on public.receivable_payments (transaction_id);
create index if not exists eir_expected_idx on public.expected_income_receipts (expected_income_id);
create index if not exists eir_tx_idx on public.expected_income_receipts (transaction_id);

-- -----------------------------------------------------------------------------
-- Allocation — the concurrency guard (§37, §74)
--
-- The problem this exists to prevent:
--
--   Bill remaining ₱1,000. Two ₱1,000 payments arrive together. Both read
--   "remaining 1,000", both conclude they fit, both insert. The bill ends up
--   ₱2,000 paid against a ₱1,000 obligation.
--
-- Neither invariant can be a CHECK constraint — both are aggregates across
-- rows. Application-level checks lose the race outright: between the read and
-- the write, the other request has already read the same balance.
--
-- The FOR UPDATE row lock is the mechanism. It serialises concurrent callers
-- against the same obligation, so the second reads the first's committed
-- total rather than a stale one.
-- -----------------------------------------------------------------------------

create or replace function public.allocate_payment(
  p_user_id         uuid,
  p_obligation_type text,   -- 'bill' | 'receivable' | 'expected_income'
  p_obligation_id   uuid,
  p_transaction_id  uuid,
  p_amount          numeric
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ob_amount    numeric(18,2);
  v_ob_currency  text;
  v_ob_status    text;
  v_ob_owner     uuid;
  v_applied      numeric(18,2);
  v_tx_amount    numeric(18,2);
  v_tx_currency  text;
  v_tx_status    text;
  v_tx_owner     uuid;
  v_tx_applied   numeric(18,2);
  v_link_id      uuid;
  v_new_status   text;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;
  if p_obligation_type not in ('bill', 'receivable', 'expected_income') then
    raise exception 'UNKNOWN_OBLIGATION_TYPE' using errcode = 'P0001';
  end if;

  -- Lock the obligation FIRST and hold it for the rest of the transaction.
  -- Everything below reads committed state because of this line.
  if p_obligation_type = 'bill' then
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.bills where id = p_obligation_id for update;
  elsif p_obligation_type = 'receivable' then
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.receivables where id = p_obligation_id for update;
  else
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.expected_income where id = p_obligation_id for update;
  end if;

  if v_ob_owner is null or v_ob_owner <> p_user_id then
    -- Same error either way: a distinguishable "forbidden" confirms existence.
    raise exception 'OBLIGATION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_ob_status = 'cancelled' then
    raise exception 'OBLIGATION_CANCELLED' using errcode = 'P0001';
  end if;

  select user_id, amount, currency_code, status
    into v_tx_owner, v_tx_amount, v_tx_currency, v_tx_status
  from public.transactions where id = p_transaction_id for update;

  if v_tx_owner is null or v_tx_owner <> p_user_id then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx_status <> 'confirmed' then
    raise exception 'TRANSACTION_NOT_CONFIRMED' using errcode = 'P0001';
  end if;
  if v_tx_currency <> v_ob_currency then
    -- Cross-currency settlement is permanently out of scope (master plan §11).
    raise exception 'CURRENCY_MISMATCH' using errcode = 'P0001';
  end if;

  -- Totals recomputed INSIDE the lock. This is the whole point.
  if p_obligation_type = 'bill' then
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.bill_payments where bill_id = p_obligation_id;
  elsif p_obligation_type = 'receivable' then
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.receivable_payments where receivable_id = p_obligation_id;
  else
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.expected_income_receipts where expected_income_id = p_obligation_id;
  end if;

  if v_applied + p_amount > v_ob_amount then
    raise exception 'EXCEEDS_OBLIGATION_REMAINING' using errcode = 'P0001';
  end if;

  -- A transaction may settle several obligations, but never more than itself.
  select coalesce((
    select sum(amount_applied) from public.bill_payments where transaction_id = p_transaction_id
  ), 0) + coalesce((
    select sum(amount_applied) from public.receivable_payments where transaction_id = p_transaction_id
  ), 0) + coalesce((
    select sum(amount_applied) from public.expected_income_receipts where transaction_id = p_transaction_id
  ), 0)
  into v_tx_applied;

  if v_tx_applied + p_amount > v_tx_amount then
    raise exception 'EXCEEDS_TRANSACTION_AMOUNT' using errcode = 'P0001';
  end if;

  if p_obligation_type = 'bill' then
    insert into public.bill_payments (user_id, bill_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  elsif p_obligation_type = 'receivable' then
    insert into public.receivable_payments (user_id, receivable_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  else
    insert into public.expected_income_receipts
      (user_id, expected_income_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  end if;

  v_applied := v_applied + p_amount;
  v_new_status := case
    when v_applied >= v_ob_amount then 'paid'
    when v_applied > 0            then 'partially_paid'
    else 'open'
  end;

  if p_obligation_type = 'bill' then
    update public.bills set status = v_new_status where id = p_obligation_id;
  elsif p_obligation_type = 'receivable' then
    update public.receivables set status = v_new_status where id = p_obligation_id;
  else
    update public.expected_income set status = v_new_status where id = p_obligation_id;
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, p_obligation_type, p_obligation_id, 'payment_linked',
     jsonb_build_object('transaction_id', p_transaction_id,
                        'amount_applied', p_amount,
                        'status', v_new_status));

  return v_link_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- unlink_payment (§55)
--
-- Removing a link never deletes the transaction — the money did move.
-- -----------------------------------------------------------------------------

create or replace function public.unlink_payment(
  p_user_id         uuid,
  p_obligation_type text,
  p_link_id         uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ob_id     uuid;
  v_owner     uuid;
  v_ob_amount numeric(18,2);
  v_applied   numeric(18,2);
  v_status    text;
begin
  if p_obligation_type = 'bill' then
    select bill_id, user_id into v_ob_id, v_owner
    from public.bill_payments where id = p_link_id;
  elsif p_obligation_type = 'receivable' then
    select receivable_id, user_id into v_ob_id, v_owner
    from public.receivable_payments where id = p_link_id;
  else
    select expected_income_id, user_id into v_ob_id, v_owner
    from public.expected_income_receipts where id = p_link_id;
  end if;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'LINK_NOT_FOUND' using errcode = 'P0002';
  end if;

  if p_obligation_type = 'bill' then
    perform 1 from public.bills where id = v_ob_id for update;
    delete from public.bill_payments where id = p_link_id;
    select amount into v_ob_amount from public.bills where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.bill_payments where bill_id = v_ob_id;
  elsif p_obligation_type = 'receivable' then
    perform 1 from public.receivables where id = v_ob_id for update;
    delete from public.receivable_payments where id = p_link_id;
    select amount into v_ob_amount from public.receivables where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.receivable_payments where receivable_id = v_ob_id;
  else
    perform 1 from public.expected_income where id = v_ob_id for update;
    delete from public.expected_income_receipts where id = p_link_id;
    select amount into v_ob_amount from public.expected_income where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.expected_income_receipts where expected_income_id = v_ob_id;
  end if;

  v_status := case
    when v_applied >= v_ob_amount then 'paid'
    when v_applied > 0            then 'partially_paid'
    else 'open'
  end;

  if p_obligation_type = 'bill' then
    update public.bills set status = v_status where id = v_ob_id;
  elsif p_obligation_type = 'receivable' then
    update public.receivables set status = v_status where id = v_ob_id;
  else
    update public.expected_income set status = v_status where id = v_ob_id;
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, p_obligation_type, v_ob_id, 'payment_unlinked',
     jsonb_build_object('status', v_status));
end;
$$;

revoke all on function public.allocate_payment from anon, authenticated;
revoke all on function public.unlink_payment   from anon, authenticated;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['bills','receivables','expected_income',
                           'bill_payments','receivable_payments','expected_income_receipts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t || '_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;


-- ======================================================================
-- 20260913000700_void_updates_obligations.sql
-- ======================================================================

-- =============================================================================
-- Voiding a transaction must release its allocations (§57).
--
-- Without this, voiding a ₱1,899 payment leaves the bill still marked paid:
-- the money no longer moved, but the obligation still believes it was settled.
-- The user sees a bill they have not paid, marked paid, with no transaction
-- behind it.
--
-- So void now: releases every link, recomputes each affected obligation's
-- status, then voids — all in one transaction.
-- =============================================================================

create or replace function public.void_transaction(
  p_user_id uuid,
  p_id      uuid,
  p_reason  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tx  public.transactions%rowtype;
  v_rec record;
begin
  select * into v_tx from public.transactions
  where id = p_id and user_id = p_user_id
  for update;

  if v_tx.id is null then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx.status = 'voided' then
    return;  -- idempotent
  end if;

  -- Release allocations and restate each obligation.
  for v_rec in
    select 'bill' as kind, bill_id as ob_id from public.bill_payments
      where transaction_id = p_id
    union all
    select 'receivable', receivable_id from public.receivable_payments
      where transaction_id = p_id
    union all
    select 'expected_income', expected_income_id from public.expected_income_receipts
      where transaction_id = p_id
  loop
    if v_rec.kind = 'bill' then
      perform 1 from public.bills where id = v_rec.ob_id for update;
      delete from public.bill_payments
        where transaction_id = p_id and bill_id = v_rec.ob_id;
      update public.bills b set status = case
          when coalesce((select sum(amount_applied) from public.bill_payments
                         where bill_id = b.id), 0) >= b.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.bill_payments
                         where bill_id = b.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where b.id = v_rec.ob_id and b.status <> 'cancelled';

    elsif v_rec.kind = 'receivable' then
      perform 1 from public.receivables where id = v_rec.ob_id for update;
      delete from public.receivable_payments
        where transaction_id = p_id and receivable_id = v_rec.ob_id;
      update public.receivables r set status = case
          when coalesce((select sum(amount_applied) from public.receivable_payments
                         where receivable_id = r.id), 0) >= r.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.receivable_payments
                         where receivable_id = r.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where r.id = v_rec.ob_id and r.status <> 'cancelled';

    else
      perform 1 from public.expected_income where id = v_rec.ob_id for update;
      delete from public.expected_income_receipts
        where transaction_id = p_id and expected_income_id = v_rec.ob_id;
      update public.expected_income e set status = case
          when coalesce((select sum(amount_applied) from public.expected_income_receipts
                         where expected_income_id = e.id), 0) >= e.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.expected_income_receipts
                         where expected_income_id = e.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where e.id = v_rec.ob_id and e.status <> 'cancelled';
    end if;

    insert into public.audit_logs
      (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
    values
      (p_user_id, p_user_id, v_rec.kind, v_rec.ob_id, 'payment_unlinked',
       jsonb_build_object('reason', 'transaction_voided', 'transaction_id', p_id));
  end loop;

  update public.transactions
  set status = 'voided',
      void_reason = nullif(btrim(coalesce(p_reason, '')), '')
  where id = p_id;

  if v_tx.source_account_id is not null then
    perform public.recalculate_account_balance(v_tx.source_account_id);
  end if;
  if v_tx.destination_account_id is not null then
    perform public.recalculate_account_balance(v_tx.destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type,
     before_data, after_data, metadata)
  values
    (p_user_id, p_user_id, 'transaction', p_id, 'transaction_voided',
     jsonb_build_object('status', 'confirmed', 'amount', v_tx.amount),
     jsonb_build_object('status', 'voided'),
     jsonb_build_object('reason', coalesce(p_reason, '')));
end;
$$;

revoke all on function public.void_transaction from anon, authenticated;


-- ======================================================================
-- 20260913000800_phase04_documents.sql
-- ======================================================================

-- =============================================================================
-- Phase 04 — Documents and Image Processing
--
-- Files live in a PRIVATE Supabase Storage bucket. Metadata lives here.
-- HelloDeploy's filesystem is never the system of record (§5) — containers are
-- replaced on every deploy.
--
-- ACCESS MODEL
--   The bucket has no policies for anon or authenticated at all. Every read
--   goes through a short-lived signed URL minted server-side after an
--   ownership check; every write goes through the upload action using the
--   service role. Storage RLS would otherwise have to re-derive ownership from
--   the object path, and a path-parsing mistake there is a cross-user file
--   leak.
--
-- RETENTION (§26)
--   The OCR-quality source survives until the extraction is resolved, not
--   until OCR merely completes — Phase 05 retries need it, and a display WebP
--   at 1800px/q85 is compressed for viewing, not for reading small print.
--
-- Idempotent.
-- =============================================================================

create table if not exists public.documents (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references auth.users (id) on delete cascade,
  document_type        text not null default 'other',

  -- Original, as received. Filename is metadata only — never a storage key.
  original_filename    text,
  original_mime_type   text,
  original_size_bytes  bigint,
  content_hash         text,

  storage_bucket       text not null default 'hello-pera-documents',
  original_path        text,
  display_path         text,
  thumbnail_path       text,

  display_mime_type    text,
  display_size_bytes   bigint,
  thumbnail_size_bytes bigint,
  width                integer,
  height               integer,
  page_count           integer,

  processing_status    text not null default 'uploaded',
  processing_error     text,
  retention_status     text not null default 'original_retained',

  is_archived          boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on column public.documents.original_filename is
  'Display metadata only. Storage keys are generated UUIDs — a user-supplied filename in a path is a traversal waiting to happen.';
comment on column public.documents.retention_status is
  'original_retained until the Phase 05 extraction is confirmed or discarded. OCR retry needs the full-quality source.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'documents_type_check') then
    alter table public.documents add constraint documents_type_check check (
      document_type in ('receipt','screenshot','bill','payment_confirmation','bank_record',
                        'ewallet_record','invoice','statement','salary_record','other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'documents_processing_check') then
    alter table public.documents add constraint documents_processing_check check (
      processing_status in ('uploaded','processing','ready','failed'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'documents_retention_check') then
    alter table public.documents add constraint documents_retention_check check (
      retention_status in ('original_retained','original_temporary','original_deleted','optimized_only'));
  end if;
end $$;

create index if not exists documents_user_created_idx
  on public.documents (user_id, created_at desc);
create index if not exists documents_user_type_idx
  on public.documents (user_id, document_type);
-- Duplicate detection in Phase 05 looks up by hash within a user.
create index if not exists documents_user_hash_idx
  on public.documents (user_id, content_hash) where content_hash is not null;
create index if not exists documents_failed_idx
  on public.documents (user_id) where processing_status = 'failed';

drop trigger if exists documents_set_updated_at on public.documents;
create trigger documents_set_updated_at before update on public.documents
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- document_links (§41)
--
-- Created now rather than in Phase 05: the many-to-many shape is what allows
-- one receipt to evidence several records, and one record to have several
-- documents. Retrofitting it after documents exist means a migration plus a
-- backfill.
-- -----------------------------------------------------------------------------

create table if not exists public.document_links (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  document_id uuid not null references public.documents (id) on delete cascade,
  entity_type text not null,
  entity_id   uuid not null,
  created_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'document_links_entity_check') then
    alter table public.document_links add constraint document_links_entity_check check (
      entity_type in ('transaction','bill','receivable','expected_income'));
  end if;
end $$;

create unique index if not exists document_links_unique_idx
  on public.document_links (document_id, entity_type, entity_id);
create index if not exists document_links_entity_idx
  on public.document_links (entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- Storage bucket
-- -----------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'hello-pera-documents',
  'hello-pera-documents',
  false,                              -- never public: these are bank records
  8388608,                            -- 8 MB. HelloDeploy's nginx caps requests
                                      -- at 10 MB; 8 leaves room for multipart
                                      -- overhead. See PLATFORM-HELLODEPLOY.md Q1.
  array['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf']
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- No policies on storage.objects for anon or authenticated.
-- Reads use server-minted signed URLs; writes use the service role.
drop policy if exists "hellopera documents are private" on storage.objects;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

alter table public.documents      enable row level security;
alter table public.documents      force  row level security;
alter table public.document_links enable row level security;
alter table public.document_links force  row level security;

drop policy if exists documents_select_own on public.documents;
create policy documents_select_own on public.documents
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists document_links_select_own on public.document_links;
create policy document_links_select_own on public.document_links
  for select to authenticated using (user_id = (select auth.uid()));

revoke all on public.documents, public.document_links from anon, authenticated;
grant select on public.documents, public.document_links to authenticated;


-- ======================================================================
-- 20260913000900_phase05_ocr_extraction.sql
-- ======================================================================

-- =============================================================================
-- Phase 05 — OCR and Financial Extraction
--
-- CORE PRINCIPLE (§4): OCR is not authoritative.
--
--   Document -> OCR -> Extraction -> User Review -> Confirmation -> Record
--
-- Nothing derived from a document may change a balance before a human confirms
-- it. That is enforced structurally: extraction rows hold JSON, never money,
-- and the only path to a transaction is confirm_extraction() below, which
-- requires the extraction to be in pending_review.
--
-- Idempotent.
-- =============================================================================

create table if not exists public.ocr_jobs (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  document_id        uuid not null references public.documents (id) on delete cascade,
  provider           text not null,
  status             text not null default 'queued',
  attempt_count      integer not null default 0,
  started_at         timestamptz,
  completed_at       timestamptz,
  failed_at          timestamptz,
  error_code         text,
  error_message_safe text,
  duration_ms        integer,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

-- One active job per document (§45). Prevents a double-click from paying a
-- provider twice for the same page.
create unique index if not exists ocr_jobs_one_active_idx
  on public.ocr_jobs (document_id)
  where status in ('queued', 'processing');

create index if not exists ocr_jobs_user_idx on public.ocr_jobs (user_id, created_at desc);
create index if not exists ocr_jobs_failed_idx
  on public.ocr_jobs (user_id) where status = 'failed';

create table if not exists public.ocr_results (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  document_id        uuid not null references public.documents (id) on delete cascade,
  ocr_job_id         uuid references public.ocr_jobs (id) on delete set null,
  provider           text not null,
  raw_text           text,
  overall_confidence numeric(4, 3),
  provider_metadata  jsonb not null default '{}'::jsonb,
  created_at         timestamptz not null default now()
);

comment on column public.ocr_results.raw_text is
  'Document text. Never written to application logs (§58) — it contains account numbers and balances.';

create index if not exists ocr_results_document_idx on public.ocr_results (document_id);

create table if not exists public.extraction_results (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,
  document_id       uuid not null references public.documents (id) on delete cascade,
  ocr_result_id     uuid references public.ocr_results (id) on delete set null,
  document_type     text,
  target_type       text,
  status            text not null default 'pending_review',
  -- Structured fields stay as JSON until a human confirms. Deliberately not
  -- numeric columns: an extraction is a proposal, and giving it the shape of a
  -- financial record invites something to read it as one.
  structured_data   jsonb not null default '{}'::jsonb,
  field_confidence  jsonb not null default '{}'::jsonb,
  validation_errors jsonb not null default '[]'::jsonb,
  corrected_data    jsonb,
  confirmed_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname='ocr_jobs_status_check') then
    alter table public.ocr_jobs add constraint ocr_jobs_status_check
      check (status in ('queued','processing','completed','failed','cancelled'));
  end if;
  if not exists (select 1 from pg_constraint where conname='extraction_status_check') then
    alter table public.extraction_results add constraint extraction_status_check
      check (status in ('pending_review','confirmed','discarded','failed'));
  end if;
  if not exists (select 1 from pg_constraint where conname='extraction_target_check') then
    alter table public.extraction_results add constraint extraction_target_check
      check (target_type is null or target_type in
        ('transaction','bill','receivable','expected_income','unknown'));
  end if;
end $$;

create index if not exists extraction_document_idx on public.extraction_results (document_id);
create index if not exists extraction_pending_idx
  on public.extraction_results (user_id, created_at desc) where status = 'pending_review';

drop trigger if exists ocr_jobs_set_updated_at on public.ocr_jobs;
create trigger ocr_jobs_set_updated_at before update on public.ocr_jobs
  for each row execute function public.set_updated_at();
drop trigger if exists extraction_set_updated_at on public.extraction_results;
create trigger extraction_set_updated_at before update on public.extraction_results
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Confirmation (§33, §83)
--
-- The ONLY path from an extraction to a financial record.
--
-- Idempotent by status transition: the row must be pending_review, and the
-- update to 'confirmed' happens in the same transaction as the record creation.
-- A double-click therefore cannot create two transactions — the second call
-- finds the row already confirmed and stops.
-- -----------------------------------------------------------------------------

create or replace function public.confirm_extraction(
  p_user_id       uuid,
  p_extraction_id uuid,
  p_entity_type   text,
  p_entity_id     uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner       uuid;
  v_status      text;
  v_document_id uuid;
begin
  -- Lock first: two simultaneous confirms must not both see pending_review.
  select user_id, status, document_id
    into v_owner, v_status, v_document_id
  from public.extraction_results
  where id = p_extraction_id
  for update;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'EXTRACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_status = 'confirmed' then
    raise exception 'ALREADY_CONFIRMED' using errcode = 'P0001';
  end if;
  if v_status <> 'pending_review' then
    raise exception 'NOT_PENDING_REVIEW' using errcode = 'P0001';
  end if;

  update public.extraction_results
  set status = 'confirmed', target_type = p_entity_type, confirmed_at = now()
  where id = p_extraction_id;

  -- Link the document to whatever the confirmation created, so the receipt is
  -- reachable from the record and vice versa.
  insert into public.document_links (user_id, document_id, entity_type, entity_id)
  values (p_user_id, v_document_id, p_entity_type, p_entity_id)
  on conflict do nothing;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'extraction', p_extraction_id, 'extraction_confirmed',
     jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id));
end;
$$;

create or replace function public.discard_extraction(
  p_user_id uuid,
  p_extraction_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_owner uuid; v_status text;
begin
  select user_id, status into v_owner, v_status
  from public.extraction_results where id = p_extraction_id for update;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'EXTRACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_status = 'confirmed' then
    -- Discarding after confirmation would orphan a real financial record.
    raise exception 'ALREADY_CONFIRMED' using errcode = 'P0001';
  end if;

  update public.extraction_results set status = 'discarded' where id = p_extraction_id;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type)
  values (p_user_id, p_user_id, 'extraction', p_extraction_id, 'extraction_discarded');
end;
$$;

revoke all on function public.confirm_extraction from anon, authenticated;
revoke all on function public.discard_extraction from anon, authenticated;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['ocr_jobs','ocr_results','extraction_results'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t||'_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t||'_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;


-- ======================================================================
-- 20260913001000_phase07_recurring_forecasting.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — Recurring Transactions and Forecasting
--
-- CORE MODELLING RULE (§4, §12):
--   A recurring rule is not money. It is a statement about what is expected to
--   happen. Generating an occurrence creates an *expectation*, never a
--   transaction — only actual money movement does that, exactly as Phase 03
--   separates an obligation from the payment that settles it.
--
-- GENERATION ARCHITECTURE (§16, the "recommended hybrid"):
--   rule_type = bill             -> generates a real row in bills
--   rule_type = expected_income  -> generates a real row in expected_income
--   rule_type = income | expense -> generates expected_events
--
--   Bills and expected income already have lifecycle, allocation and display
--   status built in Phase 03; re-implementing those on expected_events would
--   be two sets of rules for one concept. Plain recurring income and expense
--   have no such home, so they get the generic row.
--
-- IDEMPOTENCY (§18, §60, §64):
--   Generation is defined by a uniqueness constraint, not by careful code.
--   Every generated row carries (recurring_rule_id, occurrence_date) with a
--   unique index, so a double-fired scheduler, an overlapping retry and a
--   lazy top-up on page load all collide harmlessly on insert.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- recurring_rules (§7)
-- -----------------------------------------------------------------------------

create table if not exists public.recurring_rules (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references auth.users (id) on delete cascade,
  rule_type            text not null,
  name                 text not null,
  description          text,
  amount               numeric(18, 2) not null,
  currency_code        text not null default 'PHP',
  frequency            text not null,
  interval_count       integer not null default 1,
  -- §10, §11 — which day the rule lands on. Null means "same day as start".
  day_of_month         integer,
  day_of_week          integer,
  start_date           date not null,
  end_date             date,
  -- The next date not yet generated. Advanced by the generator, never by a
  -- read, so a crashed run resumes rather than skipping.
  next_occurrence_date date,
  account_id           uuid references public.accounts (id) on delete set null,
  category_id          uuid references public.categories (id) on delete set null,
  -- Carried onto generated bills / expected income so the row reads naturally.
  provider_name        text,
  source_name          text,
  is_active            boolean not null default true,
  is_paused            boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_type_check') then
    alter table public.recurring_rules add constraint recurring_rules_type_check
      check (rule_type in ('income', 'expense', 'bill', 'expected_income'));
  end if;

  -- §8 — a small, closed set. RRULE-style recurrence is explicitly out (§8).
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_frequency_check') then
    alter table public.recurring_rules add constraint recurring_rules_frequency_check
      check (frequency in ('weekly', 'biweekly', 'monthly', 'quarterly', 'yearly'));
  end if;

  -- §9 — "every N". Zero would generate the same date forever.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_interval_check') then
    alter table public.recurring_rules add constraint recurring_rules_interval_check
      check (interval_count >= 1 and interval_count <= 52);
  end if;

  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_amount_check') then
    alter table public.recurring_rules add constraint recurring_rules_amount_check
      check (amount > 0);
  end if;

  -- §10 — 29..31 are accepted and clamped to the month's last day at
  -- generation time; see lib/recurring/schedule.ts.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dom_check') then
    alter table public.recurring_rules add constraint recurring_rules_dom_check
      check (day_of_month is null or (day_of_month between 1 and 31));
  end if;

  -- §11 — ISO: 1 = Monday .. 7 = Sunday.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dow_check') then
    alter table public.recurring_rules add constraint recurring_rules_dow_check
      check (day_of_week is null or (day_of_week between 1 and 7));
  end if;

  -- §13 — an end before the start would generate nothing, silently.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dates_check') then
    alter table public.recurring_rules add constraint recurring_rules_dates_check
      check (end_date is null or end_date >= start_date);
  end if;
end $$;

create index if not exists recurring_rules_user_idx
  on public.recurring_rules (user_id, start_date);
-- The generator's own query: live rules with something still to generate.
create index if not exists recurring_rules_due_idx
  on public.recurring_rules (next_occurrence_date)
  where is_active and not is_paused;

drop trigger if exists recurring_rules_set_updated_at on public.recurring_rules;
create trigger recurring_rules_set_updated_at before update on public.recurring_rules
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- expected_events (§15)
--
-- Generic expectations for recurring income and expense. Bills and expected
-- income get native Phase 03 rows instead (§16).
-- -----------------------------------------------------------------------------

create table if not exists public.expected_events (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null references auth.users (id) on delete cascade,
  recurring_rule_id     uuid references public.recurring_rules (id) on delete cascade,
  event_type            text not null,
  name                  text not null,
  amount                numeric(18, 2) not null,
  currency_code         text not null default 'PHP',
  scheduled_date        date not null,
  status                text not null default 'scheduled',
  account_id            uuid references public.accounts (id) on delete set null,
  category_id           uuid references public.categories (id) on delete set null,
  -- §39, §40 — the transaction that fulfilled this expectation, if any.
  actual_transaction_id uuid references public.transactions (id) on delete set null,
  -- §43 — a user may exclude a single occurrence from the projection without
  -- skipping it, e.g. "this bonus is not certain enough to plan against".
  include_in_forecast   boolean not null default true,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'expected_events_type_check') then
    alter table public.expected_events add constraint expected_events_type_check
      check (event_type in ('income', 'expense', 'bill', 'expected_income'));
  end if;

  -- §15. `overdue` is NOT here: like Phase 03's display statuses it is derived
  -- from scheduled_date at read time, so it cannot be silently stale between
  -- scheduler runs.
  if not exists (select 1 from pg_constraint where conname = 'expected_events_status_check') then
    alter table public.expected_events add constraint expected_events_status_check
      check (status in ('scheduled', 'fulfilled', 'skipped', 'cancelled'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'expected_events_amount_check') then
    alter table public.expected_events add constraint expected_events_amount_check
      check (amount > 0);
  end if;

  -- A fulfilled event must say what fulfilled it, and an unfulfilled one must
  -- not pretend to (§39).
  if not exists (select 1 from pg_constraint where conname = 'expected_events_fulfilled_check') then
    alter table public.expected_events add constraint expected_events_fulfilled_check
      check (
        (status = 'fulfilled' and actual_transaction_id is not null)
        or (status <> 'fulfilled' and actual_transaction_id is null)
      );
  end if;
end $$;

-- §18 — the whole of idempotent generation, in one line. A rule cannot
-- produce the same date twice no matter how many schedulers fire.
create unique index if not exists expected_events_rule_date_uidx
  on public.expected_events (recurring_rule_id, scheduled_date)
  where recurring_rule_id is not null;

create index if not exists expected_events_user_date_idx
  on public.expected_events (user_id, scheduled_date);
create index if not exists expected_events_forecast_idx
  on public.expected_events (user_id, scheduled_date)
  where status = 'scheduled' and include_in_forecast;

drop trigger if exists expected_events_set_updated_at on public.expected_events;
create trigger expected_events_set_updated_at before update on public.expected_events
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Generated Phase 03 rows (§16, §18)
--
-- A recurring bill produces a real bill, so it inherits Phase 03's lifecycle,
-- allocation and derived status for free. The provenance columns are what make
-- that generation idempotent.
-- -----------------------------------------------------------------------------

alter table public.bills
  add column if not exists recurring_rule_id uuid references public.recurring_rules (id) on delete set null,
  add column if not exists occurrence_date date;

alter table public.expected_income
  add column if not exists recurring_rule_id uuid references public.recurring_rules (id) on delete set null,
  add column if not exists occurrence_date date;

create unique index if not exists bills_rule_occurrence_uidx
  on public.bills (recurring_rule_id, occurrence_date)
  where recurring_rule_id is not null;

create unique index if not exists expected_income_rule_occurrence_uidx
  on public.expected_income (recurring_rule_id, occurrence_date)
  where recurring_rule_id is not null;

-- -----------------------------------------------------------------------------
-- job_runs (§20a)
--
-- Introduced here because this is the first scheduler. Phases 08, 11, 13 and
-- 14 reuse it; PHASE-13 §48-51 builds the admin view over it rather than
-- inventing it late, by which point three phases would have run unprotected.
--
-- No user_id: these are system runs, not user data. Phase 13's admin view is
-- the only reader, so the table is not exposed to the client at all.
-- -----------------------------------------------------------------------------

create table if not exists public.job_runs (
  id           uuid primary key default gen_random_uuid(),
  job_type     text not null,
  status       text not null default 'running',
  started_at   timestamptz not null default now(),
  completed_at timestamptz,
  duration_ms  integer,
  error_code   text,
  metadata     jsonb not null default '{}'::jsonb
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'job_runs_status_check') then
    alter table public.job_runs add constraint job_runs_status_check
      check (status in ('running', 'succeeded', 'failed', 'partial'));
  end if;
end $$;

create index if not exists job_runs_type_started_idx
  on public.job_runs (job_type, started_at desc);
-- Finding a wedged run: one that claims to be running and never finished.
create index if not exists job_runs_running_idx
  on public.job_runs (job_type) where status = 'running';

-- -----------------------------------------------------------------------------
-- RLS
--
-- Client reads its own rows; every write goes through a server action
-- (master plan §33). `job_runs` is not user data and is not exposed at all.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['recurring_rules', 'expected_events'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t || '_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

alter table public.job_runs enable row level security;
alter table public.job_runs force  row level security;
revoke all on public.job_runs from anon, authenticated;


-- ======================================================================
-- 20260913001100_phase07_generation_rpc.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — occurrence generation and job bookkeeping
--
-- Two concerns, deliberately separate:
--
--   generate_occurrence()  inserts ONE occurrence for ONE rule, idempotently.
--   run_job_*()            the §20a advisory-lock and job_runs bookkeeping.
--
-- The date arithmetic is NOT here. It lives in lib/recurring/schedule.ts,
-- where it is unit-tested across month-end, leap years and DST — the cases
-- that actually break recurrence. SQL computes nothing it cannot be tested
-- on; it enforces uniqueness, which is the part that must be atomic.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- generate_occurrence (§16, §18, §60)
--
-- Routes by rule type to the right home, and relies on the unique indexes for
-- idempotency rather than a read-then-write check, which loses the race
-- outright: between "does it exist?" and "insert", a concurrent run has
-- already inserted.
--
-- Returns the id created, or null when the occurrence already existed.
-- -----------------------------------------------------------------------------

create or replace function public.generate_occurrence(
  p_rule_id         uuid,
  p_occurrence_date date
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.recurring_rules%rowtype;
  v_id uuid;
begin
  select * into r from public.recurring_rules where id = p_rule_id;
  if not found then
    raise exception 'RULE_NOT_FOUND' using errcode = 'P0001';
  end if;

  -- §21, §24 — a paused or ended rule generates nothing. Checked here as well
  -- as in the caller so a stale worklist cannot resurrect a stopped rule.
  if not r.is_active or r.is_paused then
    return null;
  end if;
  if p_occurrence_date < r.start_date then
    return null;
  end if;
  if r.end_date is not null and p_occurrence_date > r.end_date then
    return null;
  end if;

  if r.rule_type = 'bill' then
    insert into public.bills (
      user_id, provider_name, description, category_id, amount, currency_code,
      due_date, status, recurring_rule_id, occurrence_date
    ) values (
      r.user_id, coalesce(r.provider_name, r.name), r.description, r.category_id,
      r.amount, r.currency_code, p_occurrence_date, 'open', r.id, p_occurrence_date
    )
    on conflict do nothing
    returning id into v_id;

  elsif r.rule_type = 'expected_income' then
    insert into public.expected_income (
      user_id, source_name, description, category_id, amount, currency_code,
      expected_date, status, recurring_rule_id, occurrence_date
    ) values (
      r.user_id, coalesce(r.source_name, r.name), r.description, r.category_id,
      r.amount, r.currency_code, p_occurrence_date, 'open', r.id, p_occurrence_date
    )
    on conflict do nothing
    returning id into v_id;

  else
    insert into public.expected_events (
      user_id, recurring_rule_id, event_type, name, amount, currency_code,
      scheduled_date, status, account_id, category_id
    ) values (
      r.user_id, r.id, r.rule_type, r.name, r.amount, r.currency_code,
      p_occurrence_date, 'scheduled', r.account_id, r.category_id
    )
    on conflict do nothing
    returning id into v_id;
  end if;

  return v_id;
end $$;

revoke all on function public.generate_occurrence from anon, authenticated;

-- -----------------------------------------------------------------------------
-- advance_rule_cursor
--
-- Moves next_occurrence_date forward. Separate from generation so a failure
-- part-way through a rule's backlog leaves the cursor where work resumes,
-- rather than skipping the dates it had not reached.
-- -----------------------------------------------------------------------------

create or replace function public.advance_rule_cursor(
  p_rule_id uuid,
  p_next    date
)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.recurring_rules
     set next_occurrence_date = p_next
   where id = p_rule_id;
$$;

revoke all on function public.advance_rule_cursor from anon, authenticated;

-- -----------------------------------------------------------------------------
-- Job bookkeeping (§20a)
--
-- begin_job takes the advisory lock and opens a job_runs row, or returns null
-- when another run holds the lock. An advisory lock is released automatically
-- if the session dies, so a crashed run cannot wedge the schedule the way a
-- lock table would.
--
-- This is defence in depth. The unique indexes in the previous migration are
-- what make generation *correct*; the lock stops two runs wasting effort and
-- racing on the same rows.
-- -----------------------------------------------------------------------------

create or replace function public.begin_job(p_job_type text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not pg_try_advisory_lock(hashtext(p_job_type)) then
    return null;   -- another run owns this job type; exit without error
  end if;

  insert into public.job_runs (job_type, status)
  values (p_job_type, 'running')
  returning id into v_id;

  return v_id;
end $$;

create or replace function public.finish_job(
  p_job_id     uuid,
  p_job_type   text,
  p_status     text,
  p_error_code text default null,
  p_metadata   jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.job_runs
     set status       = p_status,
         completed_at = now(),
         duration_ms  = (extract(epoch from (now() - started_at)) * 1000)::integer,
         error_code   = p_error_code,
         metadata     = coalesce(p_metadata, '{}'::jsonb)
   where id = p_job_id;

  -- Released explicitly on the happy path; the session ending releases it
  -- anyway, which is what makes a crash safe.
  perform pg_advisory_unlock(hashtext(p_job_type));
end $$;

revoke all on function public.begin_job  from anon, authenticated;
revoke all on function public.finish_job from anon, authenticated;


-- ======================================================================
-- 20260914000100_phase07_generation_orchestrator.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — generation orchestrator, schema corrections, and scheduling
--
-- Completes the Phase 07 database layer. Three concerns:
--
--   1. Columns §15 and §66 specify that the first migration did not create.
--   2. run_recurring_generation() — the function the scheduler calls. The
--      parts existed (generate_occurrence, advance_rule_cursor, begin_job,
--      finish_job); nothing orchestrated them, so nothing generated anything.
--   3. The pg_cron schedule itself (§2, §20).
--
-- ## On putting date arithmetic in SQL
--
-- The previous migration's header says the date math lives in TypeScript and
-- not here. That was right when SQL only had to insert one occurrence it was
-- handed. It cannot hold once Postgres owns the schedule (§2: HelloDeploy has
-- no scheduler, so generation runs in the database), because the job must
-- decide *which* dates to generate with no application in the loop.
--
-- So the walk is transcribed here, and `lib/recurring/sql-parity.test.ts`
-- asserts it still agrees with `lib/recurring/schedule.ts` across every
-- frequency, interval and month-end case. That is the same device
-- `lib/finance/sql-parity.test.ts` already uses for the balance matrix, and
-- for the same reason: two hand-written copies of one rule is how a system
-- drifts into showing a number its own repair job disagrees with.
--
-- The anchor rule is preserved exactly: occurrence N is computed from the
-- rule's START DATE, never from occurrence N-1. A rule on the 31st clamps to
-- 28 February and returns to 31 March. Walking from the previous occurrence
-- would move it permanently to the 28th.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Missing columns
-- -----------------------------------------------------------------------------

-- §66 — a user who edits a generated event must not have that edit erased by
-- the next regeneration. DATA-MODEL.md already documented this column; the
-- table never had it.
alter table public.expected_events
  add column if not exists detached_from_rule boolean not null default false;

-- §15 — provenance for events materialised into another table.
alter table public.expected_events
  add column if not exists source_entity_type text;
alter table public.expected_events
  add column if not exists source_entity_id   uuid;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'expected_events_source_entity_type_check'
  ) then
    alter table public.expected_events
      add constraint expected_events_source_entity_type_check
      check (source_entity_type is null
             or source_entity_type in ('bill', 'expected_income', 'transaction'));
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- 2. Recurrence arithmetic (§8–§11)
--
-- occurrence_at(rule, step) — the transcription of occurrenceAt() in
-- lib/recurring/schedule.ts. Immutable and side-effect free, so it is safe to
-- call in a loop and cheap enough not to matter.
-- -----------------------------------------------------------------------------

create or replace function public.occurrence_at(
  p_frequency      text,
  p_interval_count integer,
  p_start_date     date,
  p_day_of_month   integer,
  p_day_of_week    integer,
  p_step           integer
)
returns date
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_day_step   integer;
  v_month_step integer;
  v_base       date;
  v_shift      integer;
  v_anchor_day integer;
  v_months     integer;
  v_first      date;      -- first of the target month
  v_day        integer;
begin
  -- Weekly family: a plain day offset from a (possibly shifted) base.
  v_day_step := case p_frequency
                  when 'weekly'   then 7
                  when 'biweekly' then 14
                  else null
                end;

  if v_day_step is not null then
    v_base := p_start_date;
    -- §11 — shift forward to the named weekday; every later occurrence keeps
    -- the same offset. isodow: 1 = Monday .. 7 = Sunday, matching the TS.
    if p_day_of_week is not null then
      v_shift := (p_day_of_week - extract(isodow from p_start_date)::integer + 7) % 7;
      v_base  := v_base + v_shift;
    end if;
    return v_base + (p_step * v_day_step * p_interval_count);
  end if;

  -- Monthly family.
  v_month_step := case p_frequency
                    when 'monthly'   then 1
                    when 'quarterly' then 3
                    when 'yearly'    then 12
                    else 1
                  end;

  v_anchor_day := coalesce(p_day_of_month, extract(day from p_start_date)::integer);
  v_months     := p_step * v_month_step * p_interval_count;

  v_first := (date_trunc('month', p_start_date::timestamp)
              + make_interval(months => v_months))::date;

  -- §10 — clamp to the last valid day of the target month. Computed
  -- explicitly rather than leaning on interval arithmetic's own clamping, so
  -- the rule is visible and the parity test can check it.
  v_day := least(
    v_anchor_day,
    extract(day from (v_first + interval '1 month' - interval '1 day'))::integer
  );

  return v_first + (v_day - 1);
end $$;

revoke all on function public.occurrence_at from anon, authenticated;

-- -----------------------------------------------------------------------------
-- 3. run_recurring_generation (§17, §19, §20, §20a, §59, §64, §65)
--
-- One function so the advisory lock is taken, held and released inside a
-- SINGLE call. begin_job/finish_job take a SESSION-level lock across two
-- separate round trips, which is correct for pg_cron (one session) but leaks
-- the lock under a pooler, where the unlock can land on a different backend
-- than the lock. §2's fallbacks are all HTTP-shaped, so that had to be closed
-- before one of them is ever used.
--
-- Idempotency does not depend on the lock. The unique indexes from the first
-- migration are what make a second run a no-op (§65: "the constraint is the
-- guarantee; the lock is the optimisation").
--
-- p_horizon_days defaults to 90 (§17) — never generate years ahead.
-- -----------------------------------------------------------------------------

create or replace function public.run_recurring_generation(
  p_horizon_days integer default 90,
  p_user_id      uuid    default null   -- null = every user; set for the lazy check
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type    text := 'recurring_generation';
  -- The lock key is per-user for a scoped run and global for the scheduled
  -- one. Without this, one user opening /forecast would take the same lock the
  -- hourly job uses, and every other user's on-load generation in that moment
  -- would skip — a lock contending on work that never overlaps, since the two
  -- runs touch different rows.
  v_lock_key    text;
  v_job_id      uuid;
  v_rule        record;
  v_today       date;
  v_horizon_end date;
  v_step        integer;
  v_date        date;
  v_created     integer := 0;
  v_examined    integer := 0;
  v_rules       integer := 0;
  v_next        date;
  v_id          uuid;
  v_status      text := 'succeeded';
  v_error       text := null;
  v_max_steps   constant integer := 4000;  -- mirrors MAX_STEPS in schedule.ts
begin
  -- §20a — skip silently when another run owns this job type. Not an error:
  -- the schedule firing over a slow run is expected, not exceptional.
  v_lock_key := case
                  when p_user_id is null then v_job_type
                  else v_job_type || ':' || p_user_id::text
                end;

  if not pg_try_advisory_lock(hashtext(v_lock_key)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status)
  values (v_job_type, 'running')
  returning id into v_job_id;

  begin
    for v_rule in
      select r.*, coalesce(p.timezone, 'Asia/Manila') as tz
        from public.recurring_rules r
        -- LEFT, not INNER: a rule whose profile row is somehow missing must
        -- still generate (falling back to Asia/Manila) rather than silently
        -- stop producing occurrences with nothing to show why.
        left join public.profiles p on p.id = r.user_id
       where r.is_active
         and not r.is_paused
         and (p_user_id is null or r.user_id = p_user_id)
    loop
      -- §47, §2 — "today" is the user's local date. cron.schedule fires in
      -- UTC; deriving the date from that would generate a day early or late
      -- for every user west or east of it.
      v_today       := (now() at time zone v_rule.tz)::date;
      v_horizon_end := v_today + p_horizon_days;

      -- §13, §24 — an ended rule generates nothing further.
      if v_rule.end_date is not null and v_rule.end_date < v_today then
        continue;
      end if;

      v_rules := v_rules + 1;
      v_next  := null;

      for v_step in 0 .. v_max_steps loop
        v_date := public.occurrence_at(
          v_rule.frequency, v_rule.interval_count, v_rule.start_date,
          v_rule.day_of_month, v_rule.day_of_week, v_step
        );

        exit when v_date > v_horizon_end;
        exit when v_rule.end_date is not null and v_date > v_rule.end_date;

        -- §59 — never before start_date. Occurrences at or before today are
        -- still generated when they fall on/after the cursor, so a rule
        -- created mid-month does not silently lose its current occurrence.
        if v_date >= v_rule.start_date
           and v_date >= coalesce(v_rule.next_occurrence_date, v_rule.start_date)
        then
          v_examined := v_examined + 1;
          v_id := public.generate_occurrence(v_rule.id, v_date);
          -- null means the unique index rejected a duplicate: the idempotent
          -- path, and the reason a second run changes nothing (§64).
          if v_id is not null then
            v_created := v_created + 1;
          end if;
        end if;

        if v_date > v_today then
          v_next := least(coalesce(v_next, v_date), v_date);
        end if;
      end loop;

      -- Advance the cursor to the first occurrence still in the future. Left
      -- where it is when the horizon holds nothing further, so work resumes
      -- there rather than skipping dates never reached.
      if v_next is not null then
        perform public.advance_rule_cursor(v_rule.id, v_next);
      end if;
    end loop;

  exception when others then
    v_status := 'failed';
    v_error  := sqlstate;
  end;

  update public.job_runs
     set status       = v_status,
         completed_at = now(),
         duration_ms  = (extract(epoch from (now() - started_at)) * 1000)::integer,
         error_code   = v_error,
         metadata     = jsonb_build_object(
                          'rules', v_rules,
                          'examined', v_examined,
                          'created', v_created,
                          'horizon_days', p_horizon_days,
                          'scoped_user', p_user_id
                        )
   where id = v_job_id;

  perform pg_advisory_unlock(hashtext(v_lock_key));

  return jsonb_build_object(
    'job_id', v_job_id, 'status', v_status, 'rules', v_rules,
    'created', v_created, 'examined', v_examined, 'error_code', v_error
  );
end $$;

revoke all on function public.run_recurring_generation from anon, authenticated;

-- -----------------------------------------------------------------------------
-- 4. Schedule (§2, §20)
--
-- Hourly rather than daily: rules belong to users in many timezones and the
-- job resolves "today" per user, so an hourly pass picks up each local
-- midnight within the hour. The body is a function call, not inline logic, so
-- the schedule stays stable while the logic changes and the same function can
-- be replayed manually by an admin (PHASE-13 §50).
--
-- Guarded: pg_cron is not available on every Supabase plan, and a migration
-- that hard-fails there would block every later migration. If this is skipped,
-- the lazy safety check in the application (§19) still generates on access —
-- correctness does not depend on cron, only timeliness.
-- -----------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;

  -- Re-scheduling the same job name would stack duplicate schedules.
  if exists (select 1 from cron.job where jobname = 'recurring_generation') then
    perform cron.unschedule('recurring_generation');
  end if;

  perform cron.schedule(
    'recurring_generation',
    '0 * * * *',
    $cron$ select public.run_recurring_generation() $cron$
  );

  raise notice 'pg_cron: recurring_generation scheduled hourly';
exception when others then
  -- insufficient_privilege, undefined_file, undefined_table — all mean the
  -- same thing operationally: no pg_cron here.
  raise warning 'pg_cron unavailable (%): recurring generation will rely on the application-side safety check (PHASE-07 §19). See PHASE-07 §2 for fallbacks.', sqlerrm;
end $$;


-- ======================================================================
-- 20260914000200_revoke_function_execute_from_public.sql
-- ======================================================================

-- =============================================================================
-- Security fix — SECURITY DEFINER functions were executable by every browser
--
-- ## The bug
--
-- Every migration since Phase 02 protected its RPCs like this:
--
--   revoke all on function public.create_account from anon, authenticated;
--
-- That statement does nothing. Postgres grants EXECUTE on a new function to
-- **PUBLIC** by default, and `anon`/`authenticated` never held a grant of
-- their own to revoke — they inherit it from PUBLIC. The function's ACL still
-- reads `=X/postgres`, which is PUBLIC holding EXECUTE.
--
-- Sixteen SECURITY DEFINER functions were therefore callable by anyone holding
-- the publishable key, through PostgREST's /rpc/ endpoint. None of them checks
-- `auth.uid()` — by design, because the write-path rule (master plan §33) says
-- only server actions using the secret key may call them, and they take the
-- owning `user_id` as a parameter and trust it.
--
-- Measured against a live database, signed in as an ordinary user:
--
--   select public.create_account('<other user id>','PWNED','cash','asset',
--                                'PHP', 999999, null);
--   -> created a ₱999,999 account owned by a different user
--
--   select public.advance_rule_cursor('<other user rule>','2030-01-01');
--   -> silently stopped that user's recurring rule for four years
--
-- RLS was never the thing that failed: these functions run as their owner, so
-- RLS does not apply to them at all. The only barrier was meant to be EXECUTE,
-- and EXECUTE was never actually withdrawn.
--
-- ## The fix
--
-- `revoke ... from public` is the statement that removes the default grant.
-- The role-specific revokes are kept alongside it: harmless, and they document
-- the intent for anyone reading only this file.
--
-- `alter default privileges` then stops the next function from arriving with
-- the same hole, which is the part that keeps this fixed rather than fixed
-- once.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Withdraw PUBLIC's default EXECUTE from every SECURITY DEFINER function.
--
-- Named explicitly rather than looped over the catalogue, so this file states
-- exactly what it changes and a reviewer can check the list against the
-- migrations that created them.
-- -----------------------------------------------------------------------------

do $$
declare
  fn text;
  names text[] := array[
    -- Phase 02 — financial core
    'create_account', 'create_transaction', 'void_transaction',
    'assert_account_access', 'recalculate_account_balance',
    'check_balance_integrity', 'assert_income_destination',
    -- Phase 03 — obligations
    'allocate_payment', 'unlink_payment',
    -- Phase 05 — OCR
    'confirm_extraction', 'discard_extraction',
    -- Phase 07 — recurring and forecasting
    'generate_occurrence', 'advance_rule_cursor',
    'begin_job', 'finish_job', 'run_recurring_generation', 'occurrence_at'
  ];
begin
  foreach fn in array names loop
    begin
      -- Every overload of the name. `revoke ... from public` is the operative
      -- clause; the roles are listed for the reader.
      execute format(
        'revoke all on function public.%I from public, anon, authenticated', fn
      );
    exception when undefined_function then
      raise notice 'skipping %: not present', fn;
    end;
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- 2. Grant EXECUTE back to service_role, which is what the server actions use.
--
-- Only the seven the application actually calls. The rest are internal helpers
-- invoked from inside other SECURITY DEFINER functions, which run as the owner
-- and therefore need no grant of their own.
-- -----------------------------------------------------------------------------

do $$
declare
  fn text;
  names text[] := array[
    'create_account', 'create_transaction', 'void_transaction',
    'allocate_payment', 'confirm_extraction', 'discard_extraction',
    'run_recurring_generation'
  ];
begin
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    raise notice 'service_role absent; skipping grants';
    return;
  end if;

  foreach fn in array names loop
    begin
      execute format('grant execute on function public.%I to service_role', fn);
    exception when undefined_function then
      raise notice 'skipping %: not present', fn;
    end;
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- 3. Stop the next function from arriving with the same hole.
--
-- Without this, the fix lasts exactly until someone adds a migration — the
-- default grant to PUBLIC applies at CREATE FUNCTION time, so every new
-- function would be born exposed and the `revoke ... from anon, authenticated`
-- idiom would keep looking like protection.
-- -----------------------------------------------------------------------------

alter default privileges in schema public revoke execute on functions from public;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    alter default privileges in schema public revoke execute on functions from authenticated;
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    alter default privileges in schema public revoke execute on functions from anon;
  end if;
end $$;


-- ======================================================================
-- 20260914000300_phase08_notifications.sql
-- ======================================================================

-- =============================================================================
-- Phase 08 — Notifications and Automation
--
-- Creates: notifications, notification_preferences, push_subscriptions.
--
-- ## The rule this schema exists to enforce
--
-- A notification INFORMS. It never changes financial state (§4): it does not
-- create a transaction, mark a bill paid, collect a receivable, move a balance
-- or confirm an extraction. Nothing here writes to a financial table, and the
-- generator added in the next migration only reads them.
--
-- ## Deduplication is a constraint, not a convention
--
-- `unique (user_id, dedupe_key)` is what makes the scheduler safe to run twice
-- (§18, §59, §61). The application's own checks are an optimisation; this is
-- the guarantee, and it holds even when two scheduler instances race.
--
-- The key shape carries the CADENCE, not just the subject (§17) — this is the
-- part that is easy to get wrong:
--
--   bill:<id>:due_soon:<due_date>      fires once, because the date occurs once
--   bill:<id>:overdue:<step>           fires once per escalation step
--
-- `due_date < today` stays true forever and the scheduler runs hourly, so
-- `bill:<id>:overdue` would fire exactly once and never escalate, while
-- `bill:<id>:overdue:<today>` would fire every single day. Keying on the
-- escalation step (§48) gives three reminders over a month, each sent once.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- notifications (§7)
-- -----------------------------------------------------------------------------

create table if not exists public.notifications (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  type            text not null,
  -- Populated when the text is actually SENT over push, so there is a record
  -- of the wording a user received. In-app rows render from `metadata` at read
  -- time instead — copy is presentation, and freezing it at generation time
  -- would mean a wording fix never reached notifications already queued.
  title           text,
  message         text,
  entity_type     text,
  entity_id       uuid,
  -- When the reminder becomes due to send. Quiet hours (§31) move this
  -- forward rather than dropping the row.
  scheduled_for   timestamptz not null default now(),
  channel         text not null default 'in_app',
  dedupe_key      text not null,
  delivery_status text not null default 'pending',
  delivered_at    timestamptz,
  read_at         timestamptz,
  -- §63 — a reminder about a bill due last March helps nobody.
  expires_at      timestamptz,
  -- The facts the copy is rendered from: provider name, amount, day counts.
  metadata        jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'notifications_type_check') then
    alter table public.notifications add constraint notifications_type_check
      check (type in (
        'bill_due_soon', 'bill_due_today', 'bill_overdue',
        'receivable_due_soon', 'receivable_overdue',
        'expected_income_upcoming', 'expected_income_missed',
        'recurring_event_upcoming',
        'ocr_review_required',
        'forecast_shortfall'
      ));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'notifications_channel_check') then
    alter table public.notifications add constraint notifications_channel_check
      check (channel in ('in_app', 'push'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'notifications_status_check') then
    alter table public.notifications add constraint notifications_status_check
      check (delivery_status in ('pending', 'sent', 'failed', 'skipped'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'notifications_entity_type_check') then
    alter table public.notifications add constraint notifications_entity_type_check
      check (entity_type is null or entity_type in (
        'bill', 'receivable', 'expected_income', 'expected_event',
        'extraction', 'forecast'
      ));
  end if;
end $$;

-- §18 — the deduplication guarantee.
create unique index if not exists notifications_dedupe_uidx
  on public.notifications (user_id, dedupe_key);

-- §66 — the notification centre reads newest first, per user.
create index if not exists notifications_user_created_idx
  on public.notifications (user_id, created_at desc);

-- §20 — the unread badge. Partial, because read rows are the majority over
-- time and the badge only ever counts unread ones.
create index if not exists notifications_unread_idx
  on public.notifications (user_id)
  where read_at is null;

-- The delivery worker's worklist.
create index if not exists notifications_pending_idx
  on public.notifications (scheduled_for)
  where delivery_status = 'pending';

-- -----------------------------------------------------------------------------
-- notification_preferences (§8, §9)
--
-- One row per user. Defaults are deliberately non-intrusive: every in-app
-- reminder on, push OFF until the browser permission is explicitly granted
-- (§13, §26) — a push default of true would be a permission prompt the user
-- never asked for.
-- -----------------------------------------------------------------------------

create table if not exists public.notification_preferences (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null unique references auth.users (id) on delete cascade,

  bill_due_soon       boolean not null default true,
  bill_overdue        boolean not null default true,
  receivable_due_soon boolean not null default true,
  receivable_overdue  boolean not null default true,
  expected_income     boolean not null default true,
  recurring_events    boolean not null default true,
  ocr_review          boolean not null default true,
  forecast_shortfall  boolean not null default true,

  in_app_enabled      boolean not null default true,
  push_enabled        boolean not null default false,

  quiet_hours_enabled boolean not null default false,
  -- Local clock times, interpreted in `timezone` below (§33).
  quiet_hours_start   time not null default '22:00',
  quiet_hours_end     time not null default '07:00',
  -- Denormalised from profiles so the scheduler needs one join, not two.
  timezone            text not null default 'Asia/Manila',

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create index if not exists notification_preferences_user_idx
  on public.notification_preferences (user_id);

-- -----------------------------------------------------------------------------
-- push_subscriptions (§24, §25)
--
-- Delivery credentials. `p256dh` and `auth` are the browser's encryption keys:
-- anyone holding them plus the VAPID private key can push to that device, so
-- the browser role gets no access to this table at all beyond its own rows,
-- and never writes them (§21).
-- -----------------------------------------------------------------------------

create table if not exists public.push_subscriptions (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  endpoint        text not null,
  p256dh          text not null,
  auth            text not null,
  user_agent      text,
  is_active       boolean not null default true,
  last_success_at timestamptz,
  last_failure_at timestamptz,
  -- §60 — three strikes and the subscription is disabled rather than retried
  -- forever. A browser that has revoked permission returns 410 permanently.
  failure_count   integer not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- §27 — one row per device. The endpoint is the device identity, and a
-- re-subscribe on the same device must update rather than duplicate.
create unique index if not exists push_subscriptions_endpoint_uidx
  on public.push_subscriptions (endpoint);

create index if not exists push_subscriptions_active_idx
  on public.push_subscriptions (user_id)
  where is_active;

-- -----------------------------------------------------------------------------
-- updated_at triggers
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['notifications', 'notification_preferences', 'push_subscriptions'] loop
    execute format('drop trigger if exists %I_set_updated_at on public.%I', t, t);
    -- notifications has no updated_at; only the two that do get the trigger.
    if t <> 'notifications' then
      execute format(
        'create trigger %I_set_updated_at before update on public.%I
         for each row execute function public.set_updated_at()', t, t);
    end if;
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- RLS (§54)
--
-- Browser SELECT on own rows only. No INSERT/UPDATE/DELETE policy for the
-- browser role: every write goes through a server action (master plan §33).
--
-- That includes marking a notification read (§21) — it looks harmless enough
-- to hand the browser an UPDATE policy, but a policy allowing `read_at` would
-- have to allow the row, and nothing in Postgres restricts an UPDATE policy to
-- one column. A server action is the narrower tool.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['notifications', 'notification_preferences', 'push_subscriptions'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('drop policy if exists %I_select_own on public.%I', t, t);
    execute format(
      'create policy %I_select_own on public.%I for select to authenticated
       using (user_id = (select auth.uid()))', t, t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- §25 — push credentials are never readable by the browser, not even the
-- user's own. The device list in /settings/notifications (§51) is served by a
-- server action that returns user_agent and dates, never the keys.
revoke select on public.push_subscriptions from authenticated;
drop policy if exists push_subscriptions_select_own on public.push_subscriptions;


-- ======================================================================
-- 20260914000400_phase08_notification_generation.sql
-- ======================================================================

-- =============================================================================
-- Phase 08 — notification generation
--
-- One scheduled function, reusing Phase 07's job infrastructure (§17 of this
-- phase, §20a of Phase 07): advisory lock, job_runs bookkeeping, pg_cron.
--
-- ## What this function may and may not do
--
-- It READS financial tables and WRITES only `notifications` (§4). It never
-- marks a bill paid, creates a transaction or confirms an extraction. If that
-- ever changes, the phase's core principle has been broken.
--
-- ## Why the inserts are bare `on conflict do nothing`
--
-- The unique index on (user_id, dedupe_key) is the deduplication guarantee
-- (§18, §61). Every insert below relies on it rather than checking first:
-- a read-then-write loses the race between "does this exist?" and "insert",
-- which is precisely the case two concurrent schedulers produce.
--
-- ## Preferences are checked in SQL, not after the fact
--
-- §42 — a user who switched a category off must not have rows created and then
-- filtered at display time, because push delivery reads the row, not the view.
--
-- ## Copy is NOT generated here
--
-- `metadata` carries the facts; `lib/notifications/copy.ts` renders the
-- sentence. Building prose in SQL would put the wording beyond reach of a test
-- and freeze it into rows already queued.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Ensure every user has a preferences row.
--
-- Created on demand rather than by a signup trigger, so users who registered
-- before this phase are covered too. Defaults come from the column defaults,
-- which §9 already made non-intrusive.
-- -----------------------------------------------------------------------------

create or replace function public.ensure_notification_preferences(p_user_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notification_preferences (user_id, timezone)
  select p_user_id, coalesce(p.timezone, 'Asia/Manila')
    from public.profiles p where p.id = p_user_id
  on conflict (user_id) do nothing;
$$;

revoke all on function public.ensure_notification_preferences from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- run_notification_generation (§34, §35, §36, §59, §61)
--
-- Hourly. Every date comparison resolves in the USER's timezone (§33): a bill
-- due "today" is today where the user lives, not where the database runs.
--
-- Windows and the escalation ladder mirror lib/notifications/rules.ts. §10
-- says not to hardcode them in multiple places; they exist twice because the
-- scheduler runs in Postgres (Phase 07 §2) and the app renders in TypeScript.
-- `lib/notifications/sql-parity.test.ts` holds the two copies to the same
-- numbers.
-- -----------------------------------------------------------------------------

create or replace function public.run_notification_generation(
  p_user_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type   text := 'notification_generation';
  v_lock_key   text;
  v_job_id     uuid;
  v_u          record;
  v_today      date;
  v_created    integer := 0;
  -- GET DIAGNOSTICS assigns a plain variable, never an expression.
  v_n          integer := 0;
  v_users      integer := 0;
  v_status     text := 'succeeded';
  v_error      text := null;

  -- Mirrors DUE_SOON_DAYS in lib/notifications/rules.ts.
  c_bill_soon       constant integer := 3;
  c_receivable_soon constant integer := 3;
  c_income_soon     constant integer := 1;
  c_event_soon      constant integer := 1;
  -- Mirrors ESCALATION_STEPS.
  c_steps           constant integer[] := array[1, 7, 30];
  -- §65 — not immediately after upload.
  c_ocr_hours       constant integer := 24;
begin
  v_lock_key := case when p_user_id is null then v_job_type
                     else v_job_type || ':' || p_user_id::text end;

  if not pg_try_advisory_lock(hashtext(v_lock_key)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status) values (v_job_type, 'running')
  returning id into v_job_id;

  begin
    for v_u in
      select p.id as user_id, coalesce(p.timezone, 'Asia/Manila') as tz, p.status as user_status
        from public.profiles p
       where (p_user_id is null or p.id = p_user_id)
    loop
      -- §43 — a suspended or disabled account does not receive ordinary
      -- financial reminders. Nudging someone to pay a bill on an account they
      -- cannot open is the wrong message at the wrong time.
      if v_u.user_status is distinct from 'active' then
        continue;
      end if;

      perform public.ensure_notification_preferences(v_u.user_id);
      v_users := v_users + 1;

      -- §33 — the user's own date, never the scheduler's.
      v_today := (now() at time zone v_u.tz)::date;

      -- ---------------------------------------------------------------------
      -- Bills (§11)
      -- ---------------------------------------------------------------------

      -- Due soon: exactly N days out, so it fires once per bill per due date.
      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select b.user_id, 'bill_due_soon', 'bill', b.id,
             'bill:' || b.id || ':due_soon:' || b.due_date,
             jsonb_build_object('name', b.provider_name, 'amount', b.amount,
                                'currency', b.currency_code,
                                'days', b.due_date - v_today, 'date', b.due_date),
             now() + interval '14 days'
        from public.bills b
        join public.notification_preferences np on np.user_id = b.user_id
       where b.user_id = v_u.user_id
         and np.bill_due_soon
         and not b.is_archived
         and b.status in ('open', 'partially_paid')
         and b.due_date = v_today + c_bill_soon
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select b.user_id, 'bill_due_today', 'bill', b.id,
             'bill:' || b.id || ':due_today:' || b.due_date,
             jsonb_build_object('name', b.provider_name, 'amount', b.amount,
                                'currency', b.currency_code, 'days', 0,
                                'date', b.due_date),
             now() + interval '14 days'
        from public.bills b
        join public.notification_preferences np on np.user_id = b.user_id
       where b.user_id = v_u.user_id
         and np.bill_due_soon
         and not b.is_archived
         and b.status in ('open', 'partially_paid')
         and b.due_date = v_today
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- Overdue: keyed on the escalation STEP, not the day. `due_date < today`
      -- stays true forever; stepping is what turns it into three reminders
      -- rather than one or thirty (§17, §48).
      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select b.user_id, 'bill_overdue', 'bill', b.id,
             'bill:' || b.id || ':overdue:' || s.step,
             jsonb_build_object('name', b.provider_name, 'amount', b.amount,
                                'currency', b.currency_code,
                                'days', b.due_date - v_today, 'date', b.due_date,
                                'step', s.step),
             now() + interval '30 days'
        from public.bills b
        join public.notification_preferences np on np.user_id = b.user_id
        cross join lateral (
          -- The highest step reached, matching escalationStepFor().
          select max(x) as step from unnest(c_steps) x
           where v_today - b.due_date >= x
        ) s
       where b.user_id = v_u.user_id
         and np.bill_overdue
         and not b.is_archived
         and b.status in ('open', 'partially_paid')
         and b.due_date < v_today
         and s.step is not null
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- ---------------------------------------------------------------------
      -- Receivables (§12)
      -- ---------------------------------------------------------------------

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select r.user_id, 'receivable_due_soon', 'receivable', r.id,
             'receivable:' || r.id || ':due_soon:' || r.due_date,
             jsonb_build_object('name', r.party_name, 'amount', r.amount,
                                'currency', r.currency_code,
                                'days', r.due_date - v_today, 'date', r.due_date),
             now() + interval '14 days'
        from public.receivables r
        join public.notification_preferences np on np.user_id = r.user_id
       where r.user_id = v_u.user_id
         and np.receivable_due_soon
         and not r.is_archived
         and r.status in ('open', 'partially_paid')
         and r.due_date is not null
         and r.due_date = v_today + c_receivable_soon
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select r.user_id, 'receivable_overdue', 'receivable', r.id,
             'receivable:' || r.id || ':overdue:' || s.step,
             jsonb_build_object('name', r.party_name, 'amount', r.amount,
                                'currency', r.currency_code,
                                'days', r.due_date - v_today, 'date', r.due_date,
                                'step', s.step),
             now() + interval '30 days'
        from public.receivables r
        join public.notification_preferences np on np.user_id = r.user_id
        cross join lateral (
          select max(x) as step from unnest(c_steps) x where v_today - r.due_date >= x
        ) s
       where r.user_id = v_u.user_id
         and np.receivable_overdue
         and not r.is_archived
         and r.status in ('open', 'partially_paid')
         and r.due_date is not null
         and r.due_date < v_today
         and s.step is not null
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- ---------------------------------------------------------------------
      -- Expected income (§13)
      --
      -- "Missed", never "overdue": nobody owes this and nothing is late.
      -- ---------------------------------------------------------------------

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select e.user_id, 'expected_income_upcoming', 'expected_income', e.id,
             'expected_income:' || e.id || ':upcoming:' || e.expected_date,
             jsonb_build_object('name', e.source_name, 'amount', e.amount,
                                'currency', e.currency_code,
                                'days', e.expected_date - v_today,
                                'date', e.expected_date),
             now() + interval '14 days'
        from public.expected_income e
        join public.notification_preferences np on np.user_id = e.user_id
       where e.user_id = v_u.user_id
         and np.expected_income
         and not e.is_archived
         and e.status in ('open', 'partially_paid')
         and e.expected_date = v_today + c_income_soon
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- Missed fires once, on the day after the expected date. There is no
      -- ladder: chasing someone about money that simply did not arrive, three
      -- times over a month, is nagging about something they cannot act on.
      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select e.user_id, 'expected_income_missed', 'expected_income', e.id,
             'expected_income:' || e.id || ':missed:' || e.expected_date,
             jsonb_build_object('name', e.source_name, 'amount', e.amount,
                                'currency', e.currency_code,
                                'days', e.expected_date - v_today,
                                'date', e.expected_date),
             now() + interval '30 days'
        from public.expected_income e
        join public.notification_preferences np on np.user_id = e.user_id
       where e.user_id = v_u.user_id
         and np.expected_income
         and not e.is_archived
         and e.status in ('open', 'partially_paid')
         and e.expected_date = v_today - 1
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- ---------------------------------------------------------------------
      -- Recurring events (§14)
      -- ---------------------------------------------------------------------

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select ev.user_id, 'recurring_event_upcoming', 'expected_event', ev.id,
             'recurring_event:' || ev.id || ':upcoming:' || ev.scheduled_date,
             jsonb_build_object('name', ev.name, 'amount', ev.amount,
                                'currency', ev.currency_code,
                                'days', ev.scheduled_date - v_today,
                                'date', ev.scheduled_date),
             now() + interval '7 days'
        from public.expected_events ev
        join public.notification_preferences np on np.user_id = ev.user_id
       where ev.user_id = v_u.user_id
         and np.recurring_events
         -- Only still-expected occurrences. A skipped or already-recorded one
         -- is not something to remind anybody about (Phase 07 §41, §42).
         and ev.status = 'scheduled'
         and ev.scheduled_date = v_today + c_event_soon
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- ---------------------------------------------------------------------
      -- OCR review (§15, §65)
      --
      -- One reminder, once the extraction has sat unreviewed for 24 hours.
      -- Reminding at upload time would fire while the user is still looking
      -- at the screen they uploaded from.
      -- ---------------------------------------------------------------------

      insert into public.notifications
        (user_id, type, entity_type, entity_id, dedupe_key, metadata, expires_at)
      select x.user_id, 'ocr_review_required', 'extraction', x.id,
             'ocr_review:' || x.id || ':1',
             jsonb_build_object('count', 1, 'date', x.created_at::date),
             now() + interval '30 days'
        from public.extraction_results x
        join public.notification_preferences np on np.user_id = x.user_id
       where x.user_id = v_u.user_id
         and np.ocr_review
         and x.status = 'pending_review'
         and x.created_at < now() - make_interval(hours => c_ocr_hours)
      on conflict do nothing;
      get diagnostics v_n = row_count; v_created := v_created + v_n;

      -- ---------------------------------------------------------------------
      -- Forecast shortfall (§16, §64)
      --
      -- Mirrors projectBalance() in lib/forecast/project.ts: opening liquid
      -- cash, plus dated inflows, minus dated outflows, walked day by day; the
      -- FIRST day the running balance goes below zero is the one reported.
      --
      -- Written here rather than called from the app because §19 says
      -- generation must not depend on the user opening a page — and a
      -- shortfall warning that only appears once you look at the forecast is
      -- precisely the warning you did not get.
      --
      -- §64's "do not notify on every recalculation" is handled by the dedupe
      -- key, which carries the shortfall DATE: an unchanged projection reuses
      -- the key and stays quiet, while a shortfall that moves earlier is a new
      -- key and notifies again.
      -- ---------------------------------------------------------------------

      if exists (select 1 from public.notification_preferences np
                  where np.user_id = v_u.user_id and np.forecast_shortfall) then

        declare
          v_currency text;
          v_opening  numeric(18,2);
          v_first    date;
          v_amount   numeric(18,2);
        begin
          select coalesce(p.default_currency, 'PHP') into v_currency
            from public.profiles p where p.id = v_u.user_id;

          -- §32 of Phase 07 — liquid ASSET accounts only. An investment is not
          -- money to spend this month, and a liability balance is a debt.
          select coalesce(sum(a.current_balance), 0) into v_opening
            from public.accounts a
           where a.user_id = v_u.user_id
             and not a.is_archived
             and a.nature = 'asset'
             and a.type in ('cash', 'bank', 'gcash', 'maya', 'paypal')
             and a.currency_code = v_currency;

          with movements as (
            select b.due_date as d, -b.amount as delta
              from public.bills b
             where b.user_id = v_u.user_id and not b.is_archived
               and b.status in ('open', 'partially_paid')
               and b.currency_code = v_currency
               and b.due_date between v_today and v_today + 30
            union all
            select e.expected_date, e.amount
              from public.expected_income e
             where e.user_id = v_u.user_id and not e.is_archived
               and e.status in ('open', 'partially_paid')
               and e.currency_code = v_currency
               and e.expected_date between v_today and v_today + 30
            union all
            select ev.scheduled_date,
                   case when ev.event_type = 'income' then ev.amount else -ev.amount end
              from public.expected_events ev
             where ev.user_id = v_u.user_id
               -- Skipped, cancelled and already-recorded occurrences are out,
               -- and so are ones the user excluded from the projection.
               and ev.status = 'scheduled'
               and ev.include_in_forecast
               and ev.currency_code = v_currency
               and ev.scheduled_date between v_today and v_today + 30
            -- Receivables are deliberately absent: Phase 07 §31 keeps them out
            -- of the default projection, and a reminder must not be based on
            -- money less certain than the forecast page itself assumes.
          ),
          daily as (
            select d, sum(delta) as delta from movements group by d
          ),
          running as (
            select d, v_opening + sum(delta) over (order by d) as balance from daily
          )
          select r.d, -r.balance into v_first, v_amount
            from running r where r.balance < 0 order by r.d limit 1;

          if v_first is not null then
            insert into public.notifications
              (user_id, type, entity_type, dedupe_key, metadata, expires_at)
            values
              (v_u.user_id, 'forecast_shortfall', 'forecast',
               'forecast_shortfall:' || v_u.user_id || ':' || v_first,
               jsonb_build_object('date', v_first, 'amount', v_amount,
                                  'currency', v_currency),
               now() + interval '14 days')
            on conflict do nothing;
            get diagnostics v_n = row_count; v_created := v_created + v_n;
          end if;
        end;
      end if;

    end loop;

  exception when others then
    v_status := 'failed';
    v_error  := sqlstate;
  end;

  update public.job_runs
     set status = v_status, completed_at = now(),
         duration_ms = (extract(epoch from (now() - started_at)) * 1000)::integer,
         error_code = v_error,
         metadata = jsonb_build_object('users', v_users, 'created', v_created,
                                       'scoped_user', p_user_id)
   where id = v_job_id;

  perform pg_advisory_unlock(hashtext(v_lock_key));

  return jsonb_build_object('job_id', v_job_id, 'status', v_status,
                            'users', v_users, 'created', v_created,
                            'error_code', v_error);
end $$;

revoke all on function public.run_notification_generation from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.run_notification_generation to service_role;
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- Cleanup (§22, §73)
--
-- Expired and long-read notifications are deleted rather than kept forever.
-- A notification centre that never forgets becomes a place nobody looks.
-- -----------------------------------------------------------------------------

create or replace function public.run_notification_cleanup()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type text := 'notification_cleanup';
  v_job_id uuid;
  v_deleted integer := 0;
begin
  if not pg_try_advisory_lock(hashtext(v_job_type)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status) values (v_job_type, 'running')
  returning id into v_job_id;

  delete from public.notifications
   where (expires_at is not null and expires_at < now())
      or (read_at is not null and read_at < now() - interval '90 days');
  get diagnostics v_deleted = row_count;

  update public.job_runs
     set status = 'succeeded', completed_at = now(),
         duration_ms = (extract(epoch from (now() - started_at)) * 1000)::integer,
         metadata = jsonb_build_object('deleted', v_deleted)
   where id = v_job_id;

  perform pg_advisory_unlock(hashtext(v_job_type));
  return jsonb_build_object('job_id', v_job_id, 'deleted', v_deleted);
end $$;

revoke all on function public.run_notification_cleanup from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- Schedule (§35) — hourly generation, daily cleanup.
--
-- Guarded exactly as Phase 07's is: pg_cron is not on every Supabase plan and
-- a hard failure here would block every later migration.
-- -----------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;

  if exists (select 1 from cron.job where jobname = 'notification_generation') then
    perform cron.unschedule('notification_generation');
  end if;
  perform cron.schedule('notification_generation', '5 * * * *',
                        $cron$ select public.run_notification_generation() $cron$);

  if exists (select 1 from cron.job where jobname = 'notification_cleanup') then
    perform cron.unschedule('notification_cleanup');
  end if;
  perform cron.schedule('notification_cleanup', '30 3 * * *',
                        $cron$ select public.run_notification_cleanup() $cron$);

  raise notice 'pg_cron: notification jobs scheduled';
exception when others then
  raise warning 'pg_cron unavailable (%): notifications will rely on the application-side check (PHASE-08 §19/§34). See PHASE-07 §2 for fallbacks.', sqlerrm;
end $$;


-- ======================================================================
-- 20260914000500_phase09_monetization.sql
-- ======================================================================

-- =============================================================================
-- Phase 09 — Monetization Foundation
--
-- Creates: plans, plan_entitlements, subscriptions, usage_records,
--          subscription_events, feature_flags, and increment_usage().
--
-- ## The rule this schema exists to enforce
--
-- §4: capability is decided by ENTITLEMENTS, never by a plan name compared in
-- application code. Raising a limit must be a data change, not a deploy. That
-- is why `plan_entitlements` is a key/value table rather than a column per
-- feature — a new entitlement is an INSERT, not a migration.
--
-- ## Free is the absence of a row
--
-- §11 offers two models and recommends this one: a user with no paid
-- subscription resolves to Free. It keeps signup free of a write, and it makes
-- the fail-closed path the same as the default path — if subscription lookup
-- breaks, the answer is already Free (§53), rather than depending on a row
-- that might be missing.
--
-- ## Why the write policies are absent, specifically
--
-- §47: this is the phase where a client write would be most directly
-- profitable. An INSERT into `subscriptions` is free Premium; an UPDATE of
-- `usage_records.quantity` is an unlimited quota. Neither table gets an
-- INSERT/UPDATE/DELETE policy for the browser role, so neither has a
-- client-reachable path at all.
--
-- ## usage_records was owed by Phase 05
--
-- `PHASE-05` §60 and `DATA-MODEL.md` both say Phase 05 creates this table with
-- exactly the shape Phase 09 needs, so that Phase 09 adds enforcement without
-- a migration. It was never built. Creating it here is safe — nothing has
-- written to it, so there is no backfill — and it closes Phase 05's own
-- outstanding criterion.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- plans (§6, §7)
--
-- `code` is the logic key and is never a display name (§7). Pricing is
-- nullable because §6 says it stays provisional until the economics are
-- settled, and a placeholder price rendered as fact is worse than none.
-- -----------------------------------------------------------------------------

create table if not exists public.plans (
  id               uuid primary key default gen_random_uuid(),
  code             text not null unique,
  name             text not null,
  description      text,
  is_active        boolean not null default true,
  -- Whether the plan appears on pricing surfaces. A grandfathered or internal
  -- plan stays active without being offered.
  is_public        boolean not null default true,
  billing_interval text,
  price_amount     numeric(18, 2),
  currency_code    text not null default 'PHP',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'plans_code_check') then
    alter table public.plans add constraint plans_code_check
      check (code in ('free', 'premium'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'plans_interval_check') then
    alter table public.plans add constraint plans_interval_check
      check (billing_interval is null or billing_interval in ('month', 'year'));
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- plan_entitlements (§8, §9)
--
-- `value_json` rather than a typed column because entitlements are genuinely
-- heterogeneous: a limit is a number, a capability is a boolean, and a horizon
-- is a number that will change. §9 warns against undocumented keys, so the
-- check constraint is the registry — a typo becomes an error rather than an
-- entitlement that silently resolves to its safe default forever.
-- -----------------------------------------------------------------------------

create table if not exists public.plan_entitlements (
  id              uuid primary key default gen_random_uuid(),
  plan_id         uuid not null references public.plans (id) on delete cascade,
  entitlement_key text not null,
  value_json      jsonb not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'plan_entitlements_key_check'
  ) then
    alter table public.plan_entitlements add constraint plan_entitlements_key_check
      check (entitlement_key in (
        'ocr_monthly_limit',
        'ai_monthly_limit',
        'advanced_analytics',
        -- §24 — a NUMBER, not a boolean. Phase 07 builds 30/60/90 and says
        -- plainly that longer horizons extrapolate past the evidence, so the
        -- entitlement caps at what exists and raising it is a data change.
        'forecast_horizon_days',
        'export_enabled',
        -- §27 — `ads_shown`, deliberately NOT `ads_enabled`. Phase 10's
        -- system-wide kill switch is `ads_enabled_global`, and two controls
        -- one word apart with opposite scopes would be confused during the
        -- incident where the kill switch matters.
        'ads_shown',
        'document_retention_days',
        'max_documents',
        'max_accounts',
        'premium_support'
      ));
  end if;
end $$;

create unique index if not exists plan_entitlements_plan_key_uidx
  on public.plan_entitlements (plan_id, entitlement_key);

-- -----------------------------------------------------------------------------
-- subscriptions (§10, §11)
--
-- Provider columns are generic on purpose (§40): nothing Stripe-shaped or
-- Paddle-shaped belongs in business logic, so the adapter keeps its own detail
-- in `subscription_events.payload` and only the two ids surface here.
-- -----------------------------------------------------------------------------

create table if not exists public.subscriptions (
  id                       uuid primary key default gen_random_uuid(),
  user_id                  uuid not null references auth.users (id) on delete cascade,
  plan_id                  uuid not null references public.plans (id) on delete restrict,
  status                   text not null default 'inactive',
  provider                 text,
  provider_customer_id     text,
  provider_subscription_id text,
  current_period_start     timestamptz,
  current_period_end       timestamptz,
  cancel_at_period_end     boolean not null default false,
  -- §41, §42 — modelled now so Phase 11 does not need a migration to start a
  -- trial or honour a grace period.
  trial_end                timestamptz,
  grace_period_end         timestamptz,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'subscriptions_status_check') then
    alter table public.subscriptions add constraint subscriptions_status_check
      check (status in (
        'active', 'trialing', 'past_due', 'grace', 'cancelled', 'expired', 'inactive'
      ));
  end if;
end $$;

-- One live subscription per user. A second row would make "which plan is this
-- person on?" ambiguous, and §12 requires one answer.
create unique index if not exists subscriptions_user_uidx
  on public.subscriptions (user_id);

create index if not exists subscriptions_status_idx
  on public.subscriptions (status)
  where status in ('active', 'trialing', 'grace');

-- -----------------------------------------------------------------------------
-- usage_records (§14, §15, §16, §31)
--
-- Owed by Phase 05; see the header. The unique key is what makes the atomic
-- increment possible, which is what makes §31's race safe.
-- -----------------------------------------------------------------------------

create table if not exists public.usage_records (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users (id) on delete cascade,
  feature_key  text not null,
  -- Calendar month in the USER's timezone (§16, §18) — dates, not instants,
  -- because a period boundary is a calendar fact.
  period_start date not null,
  period_end   date not null,
  quantity     integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'usage_records_feature_check') then
    alter table public.usage_records add constraint usage_records_feature_check
      check (feature_key in ('ocr_jobs', 'ai_queries', 'document_uploads', 'exports'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'usage_records_quantity_check') then
    alter table public.usage_records add constraint usage_records_quantity_check
      check (quantity >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'usage_records_period_check') then
    alter table public.usage_records add constraint usage_records_period_check
      check (period_end >= period_start);
  end if;
end $$;

create unique index if not exists usage_records_user_feature_period_uidx
  on public.usage_records (user_id, feature_key, period_start);

-- -----------------------------------------------------------------------------
-- subscription_events (§37, §38)
--
-- Phase 11 writes these from webhooks. The unique key is what makes replay
-- safe: a provider that delivers the same event twice — which every provider
-- does — must not apply it twice.
-- -----------------------------------------------------------------------------

create table if not exists public.subscription_events (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid references auth.users (id) on delete set null,
  subscription_id   uuid references public.subscriptions (id) on delete set null,
  provider          text not null,
  provider_event_id text not null,
  event_type        text not null,
  payload           jsonb not null default '{}'::jsonb,
  processing_status text not null default 'pending',
  processed_at      timestamptz,
  created_at        timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'subscription_events_status_check'
  ) then
    alter table public.subscription_events add constraint subscription_events_status_check
      check (processing_status in ('pending', 'processed', 'failed', 'ignored'));
  end if;
end $$;

create unique index if not exists subscription_events_provider_event_uidx
  on public.subscription_events (provider, provider_event_id);

-- -----------------------------------------------------------------------------
-- feature_flags (§50, §51, §52)
--
-- System-wide kill switches, distinct from per-user entitlements. The
-- distinction that matters: `ads_enabled_global` turns off all advertising;
-- `ads_shown` decides whether a given user would have seen any. An ad renders
-- only when both permit it.
-- -----------------------------------------------------------------------------

create table if not exists public.feature_flags (
  id         uuid primary key default gen_random_uuid(),
  key        text not null unique,
  enabled    boolean not null default false,
  config     jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);

-- -----------------------------------------------------------------------------
-- Seed
--
-- Plans and their entitlements ship with the migration so a fresh database
-- resolves correctly with no application bootstrap. Values are §8's own
-- placeholders — `on conflict do nothing` so re-running never overwrites a
-- value an operator has since tuned.
-- -----------------------------------------------------------------------------

insert into public.plans (code, name, description, is_active, is_public, billing_interval)
values
  ('free', 'Free',
   'Everything you need to track your money by hand.', true, true, null),
  ('premium', 'Premium',
   'Higher limits, longer forecasts and no ads.', true, true, 'month')
on conflict (code) do nothing;

do $$
declare
  v_free    uuid;
  v_premium uuid;
begin
  select id into v_free    from public.plans where code = 'free';
  select id into v_premium from public.plans where code = 'premium';

  insert into public.plan_entitlements (plan_id, entitlement_key, value_json) values
    -- Free — §22: "Free should remain genuinely useful." A forecast the user
    -- has never seen is one they will not pay for (§24), so 30 days is free.
    (v_free, 'ocr_monthly_limit',       '30'::jsonb),
    (v_free, 'ai_monthly_limit',        '5'::jsonb),
    (v_free, 'advanced_analytics',      'false'::jsonb),
    (v_free, 'forecast_horizon_days',   '30'::jsonb),
    (v_free, 'export_enabled',          'false'::jsonb),
    (v_free, 'ads_shown',               'true'::jsonb),
    (v_free, 'document_retention_days', '30'::jsonb),
    -- null means no limit. §28: "Do not limit accounts unnecessarily unless
    -- needed for pricing." The key exists so it can be set without a
    -- migration; it is simply not used yet.
    (v_free, 'max_documents',           'null'::jsonb),
    (v_free, 'max_accounts',            'null'::jsonb),
    (v_free, 'premium_support',         'false'::jsonb),

    -- Premium — capped at what Phase 07 actually built (§24).
    (v_premium, 'ocr_monthly_limit',       '500'::jsonb),
    (v_premium, 'ai_monthly_limit',        '100'::jsonb),
    (v_premium, 'advanced_analytics',      'true'::jsonb),
    (v_premium, 'forecast_horizon_days',   '90'::jsonb),
    (v_premium, 'export_enabled',          'true'::jsonb),
    (v_premium, 'ads_shown',               'false'::jsonb),
    (v_premium, 'document_retention_days', '365'::jsonb),
    (v_premium, 'max_documents',           'null'::jsonb),
    (v_premium, 'max_accounts',            'null'::jsonb),
    (v_premium, 'premium_support',         'true'::jsonb)
  on conflict (plan_id, entitlement_key) do nothing;
end $$;

-- §50 — staged rollout switches. billing_enabled is OFF: §52 requires
-- HelloPera to work fully with monetization disabled, and that is the
-- development posture until Phase 11 has a real provider behind it.
insert into public.feature_flags (key, enabled, config) values
  ('billing_enabled',    false, '{"note": "Phase 11 turns this on with a real provider."}'::jsonb),
  ('premium_enabled',    false, '{}'::jsonb),
  ('ads_enabled_global', false, '{"note": "Phase 10 owns ad rendering."}'::jsonb),
  ('ai_enabled',         false, '{"note": "Phase 12."}'::jsonb),
  ('ocr_enabled',        true,  '{}'::jsonb),
  ('push_enabled',       true,  '{}'::jsonb)
on conflict (key) do nothing;

-- -----------------------------------------------------------------------------
-- increment_usage (§31)
--
-- Atomic by construction. The race §31 describes — 29/30, two OCR jobs start,
-- both read 29, both proceed — cannot happen here because the read and the
-- write are one statement and the unique index serialises them.
--
-- Returns the quantity AFTER incrementing, so the caller can compare against
-- the limit without a second read that could see a third writer's value.
-- -----------------------------------------------------------------------------

create or replace function public.increment_usage(
  p_user_id      uuid,
  p_feature_key  text,
  p_period_start date,
  p_period_end   date,
  p_quantity     integer default 1
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_quantity integer;
begin
  insert into public.usage_records
    (user_id, feature_key, period_start, period_end, quantity)
  values
    (p_user_id, p_feature_key, p_period_start, p_period_end, p_quantity)
  on conflict (user_id, feature_key, period_start) do update
    set quantity   = public.usage_records.quantity + excluded.quantity,
        updated_at = now()
  returning quantity into v_quantity;

  return v_quantity;
end $$;

revoke all on function public.increment_usage from public, anon, authenticated;

do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.increment_usage to service_role;
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- updated_at triggers
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array[
    'plans', 'plan_entitlements', 'subscriptions', 'usage_records', 'feature_flags'
  ] loop
    execute format('drop trigger if exists %I_set_updated_at on public.%I', t, t);
    execute format(
      'create trigger %I_set_updated_at before update on public.%I
       for each row execute function public.set_updated_at()', t, t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- RLS (§47, §48)
-- -----------------------------------------------------------------------------

-- User-owned: SELECT own rows, and no write policy of any kind. An INSERT here
-- is free Premium; an UPDATE of quantity is an unlimited quota.
do $$
declare t text;
begin
  foreach t in array array['subscriptions', 'usage_records'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('drop policy if exists %I_select_own on public.%I', t, t);
    execute format(
      'create policy %I_select_own on public.%I for select to authenticated
       using (user_id = (select auth.uid()))', t, t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- Catalogue: readable by any signed-in user so the UI can render tiers and
-- explain what Premium includes (§47). Written only by migration or an
-- audited admin action.
do $$
declare t text;
begin
  foreach t in array array['plans', 'plan_entitlements'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('drop policy if exists %I_select_all on public.%I', t, t);
    execute format(
      'create policy %I_select_all on public.%I for select to authenticated
       using (true)', t, t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- Operational: no browser access at all, like job_runs. Feature flags are read
-- server-side; subscription events are raw provider payloads and may carry
-- billing detail that is none of the browser's business.
do $$
declare t text;
begin
  foreach t in array array['feature_flags', 'subscription_events'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;


-- ======================================================================
-- 20260914000600_gate_rate_limits.sql
-- ======================================================================

-- =============================================================================
-- Pre-public-launch gate — authentication rate limiting
--
-- Master plan §54a lists "Rate limiting active on authentication endpoints"
-- among the items that must pass before Phase 10 publishes anything.
-- PHASE-14 §38 marks it a partial gate item and extends coverage later.
--
-- ## Why Postgres and not memory
--
-- HelloDeploy runs a single replica, so an in-process counter would appear to
-- work — right up to the first redeploy or container restart, which resets
-- every limit at exactly the moment a deploy makes the service most
-- interesting to probe. A table survives restarts and is already here; Redis
-- is explicitly out of scope.
--
-- ## Operational, not user-owned
--
-- A rate-limit row is keyed by email or IP and exists before anyone is
-- authenticated, so it has no `user_id` and no browser access at all. Reading
-- it would tell an attacker exactly how many attempts remain.
--
-- Idempotent.
-- =============================================================================

create table if not exists public.rate_limits (
  -- "<action>:<identifier>", built by rateLimitKey() in
  -- lib/security/rate-limit.ts. The primary key IS the bucket, so there is no
  -- second index to keep and no ambiguity about which row to touch.
  key               text primary key,
  attempts          integer not null default 0,
  window_started_at timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'rate_limits_attempts_check') then
    alter table public.rate_limits add constraint rate_limits_attempts_check
      check (attempts >= 0);
  end if;
end $$;

-- Lets the cleanup job find stale buckets without scanning the table.
create index if not exists rate_limits_window_idx
  on public.rate_limits (window_started_at);

-- -----------------------------------------------------------------------------
-- check_rate_limit
--
-- Records an attempt and returns whether it is allowed, in ONE statement.
--
-- The check-then-increment alternative loses the race that matters: a
-- credential-stuffing script sends twenty requests at once, all twenty read
-- "3 attempts so far", and all twenty proceed. `insert … on conflict do
-- update` with the decision computed inside the statement cannot be
-- interleaved that way.
--
-- Returns (allowed, attempts, retry_after_seconds). The policy — limit and
-- window — is passed in rather than stored, so it stays in
-- lib/security/rate-limit.ts where it is documented and tested.
-- -----------------------------------------------------------------------------

create or replace function public.check_rate_limit(
  p_key            text,
  p_limit          integer,
  p_window_seconds integer
)
returns table (allowed boolean, attempts integer, retry_after_seconds integer)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_attempts integer;
  v_started  timestamptz;
  v_elapsed  integer;
begin
  insert into public.rate_limits (key, attempts, window_started_at, updated_at)
  values (p_key, 1, now(), now())
  on conflict (key) do update
    set
      -- A window that has fully elapsed restarts at 1; otherwise this attempt
      -- adds to the running count. Both branches are evaluated inside the
      -- single UPDATE, so two concurrent callers serialise on the row lock.
      attempts = case
        when now() - public.rate_limits.window_started_at
             >= make_interval(secs => p_window_seconds)
        then 1
        else public.rate_limits.attempts + 1
      end,
      window_started_at = case
        when now() - public.rate_limits.window_started_at
             >= make_interval(secs => p_window_seconds)
        then now()
        else public.rate_limits.window_started_at
      end,
      updated_at = now()
  returning public.rate_limits.attempts, public.rate_limits.window_started_at
    into v_attempts, v_started;

  v_elapsed := greatest(0, floor(extract(epoch from (now() - v_started)))::integer);

  return query select
    v_attempts <= p_limit,
    v_attempts,
    case
      when v_attempts <= p_limit then 0
      else greatest(1, p_window_seconds - v_elapsed)
    end;
end $$;

revoke all on function public.check_rate_limit from public, anon, authenticated;

do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.check_rate_limit to service_role;
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- Cleanup
--
-- Buckets are worthless once their window has passed. Without this the table
-- grows one row per email anyone ever typed, forever.
-- -----------------------------------------------------------------------------

create or replace function public.run_rate_limit_cleanup()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_deleted integer;
begin
  delete from public.rate_limits where window_started_at < now() - interval '24 hours';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end $$;

revoke all on function public.run_rate_limit_cleanup from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- RLS — operational, no browser access.
-- -----------------------------------------------------------------------------

alter table public.rate_limits enable row level security;
alter table public.rate_limits force row level security;
revoke all on public.rate_limits from anon, authenticated;

do $$
begin
  create extension if not exists pg_cron;

  if exists (select 1 from cron.job where jobname = 'rate_limit_cleanup') then
    perform cron.unschedule('rate_limit_cleanup');
  end if;
  perform cron.schedule('rate_limit_cleanup', '15 4 * * *',
                        $cron$ select public.run_rate_limit_cleanup() $cron$);

  raise notice 'pg_cron: rate_limit_cleanup scheduled daily';
exception when others then
  raise warning 'pg_cron unavailable (%): stale rate-limit rows will accumulate until cleaned manually.', sqlerrm;
end $$;


-- ======================================================================
-- 20260914000700_profiles_first_last_name.sql
-- ======================================================================

-- =============================================================================
-- profiles: first_name / last_name, with full_name as a generated column
--
-- `full_name` was a single nullable column, and the only thing that read it
-- recovered a first name with `full_name.split(' ')[0]`. That heuristic is
-- wrong for a large share of Filipino names — "Ma. Cristina Reyes" greets the
-- user as "Ma." — and it was the sole reason the column was read at all.
--
-- Google already sends `given_name` and `family_name` in raw_user_meta_data.
-- The trigger below now reads them instead of throwing the structure away and
-- re-deriving it badly.
--
-- ## Why full_name becomes GENERATED rather than a column the app maintains
--
-- Two writable columns holding overlapping truth drift. The application would
-- have to remember to update the display name on every path that touches a
-- part — register, settings, and any future admin edit — and the one that
-- forgets produces a profile whose displayed name disagrees with its own
-- fields. A generated column cannot disagree.
--
-- ## The nullif is load-bearing
--
-- Without it, a user with no name gets `''` rather than NULL. Every display
-- fallback in the app is `profile.full_name ?? email`, and `??` does not catch
-- the empty string — so the sidebar and top bar would render a blank name and
-- blank avatar initials instead of falling back to the email.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. The new columns.
-- -----------------------------------------------------------------------------

alter table public.profiles add column if not exists first_name text;
alter table public.profiles add column if not exists last_name  text;

-- -----------------------------------------------------------------------------
-- 2. Convert full_name.
--
-- Guarded on the column still being an ordinary one, so re-running is a no-op
-- rather than an error. The backfill runs BEFORE the drop: nothing has been
-- applied to a live database yet, but a migration that would lose data if it
-- ever met some is a migration written wrong.
-- -----------------------------------------------------------------------------

do $$
begin
  if exists (
    select 1 from information_schema.columns
     where table_schema = 'public'
       and table_name   = 'profiles'
       and column_name  = 'full_name'
       and is_generated = 'NEVER'
  ) then
    -- Everything before the first space is the given name; the remainder is
    -- the surname. The same heuristic this migration exists to retire, used
    -- once, to avoid discarding names that already exist.
    update public.profiles
       set first_name = coalesce(first_name, nullif(split_part(full_name, ' ', 1), '')),
           last_name  = coalesce(
             last_name,
             nullif(substr(full_name, length(split_part(full_name, ' ', 1)) + 2), '')
           )
     where full_name is not null;

    alter table public.profiles drop column full_name;

    alter table public.profiles
      add column full_name text generated always as (
        nullif(trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), '')
      ) stored;
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- 3. The signup trigger.
--
-- Structured fields first, split only as a last resort for providers that send
-- none. `role` and `status` stay hardcoded: OAuth metadata is attacker-adjacent
-- and sign-up payloads are client-controlled, so neither may ever influence
-- authorization.
--
-- `full_name` is absent from the INSERT because it is generated — naming it
-- would make the statement fail outright.
-- -----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_full  text;
  v_first text;
  v_last  text;
begin
  v_full := coalesce(
    new.raw_user_meta_data ->> 'full_name',
    new.raw_user_meta_data ->> 'name'
  );

  -- Google supplies these directly; email signup sends them from the form.
  v_first := nullif(trim(coalesce(new.raw_user_meta_data ->> 'given_name', '')), '');
  v_last  := nullif(trim(coalesce(new.raw_user_meta_data ->> 'family_name', '')), '');

  if v_first is null and v_last is null and v_full is not null then
    v_first := nullif(split_part(v_full, ' ', 1), '');
    v_last  := nullif(substr(v_full, length(split_part(v_full, ' ', 1)) + 2), '');
  end if;

  insert into public.profiles (id, email, first_name, last_name, avatar_url, role, status)
  values (
    new.id,
    new.email,
    v_first,
    v_last,
    coalesce(
      new.raw_user_meta_data ->> 'avatar_url',
      new.raw_user_meta_data ->> 'picture'
    ),
    'user',
    'active'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();


-- ======================================================================
-- 20260914000800_phase11_billing.sql
-- ======================================================================

-- =============================================================================
-- Phase 11 — Premium Billing: customer mapping and payment history
--
-- The provider-independent half. No adapter, no checkout, no provider names:
-- §6 leaves provider selection open and §40 of Phase 09 forbids baking one
-- into the domain model, so `provider` is a plain text column and everything
-- provider-shaped lives in `subscription_events.payload`.
--
-- ## What is deliberately NOT stored
--
-- §37, §38 and criterion 24: HelloPera never stores a card number, a CVV, an
-- expiry, or bank credentials. The provider's hosted checkout and portal hold
-- those, which is what keeps this application out of PCI scope entirely. The
-- columns below are amounts, dates, opaque provider ids and a receipt URL —
-- enough to show someone their own billing history and nothing more.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- billing_customers (§11)
--
-- One row per user per provider. Exists because a provider identifies people
-- by its own customer id, and a webhook arrives carrying that id and nothing
-- else — without this table there is no way back to a HelloPera user.
-- -----------------------------------------------------------------------------

create table if not exists public.billing_customers (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references auth.users (id) on delete cascade,
  provider             text not null,
  provider_customer_id text not null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

-- The lookup a webhook performs: provider + their id -> our user.
create unique index if not exists billing_customers_provider_customer_uidx
  on public.billing_customers (provider, provider_customer_id);

-- One customer record per provider per user. A second would make "which
-- customer is this person?" ambiguous at exactly the moment money moves.
create unique index if not exists billing_customers_user_provider_uidx
  on public.billing_customers (user_id, provider);

-- -----------------------------------------------------------------------------
-- billing_history (§34)
-- -----------------------------------------------------------------------------

create table if not exists public.billing_history (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null references auth.users (id) on delete cascade,
  subscription_id       uuid references public.subscriptions (id) on delete set null,
  provider              text not null,
  provider_invoice_id   text,
  provider_payment_id   text,
  amount                numeric(18, 2) not null,
  currency_code         text not null default 'PHP',
  status                text not null,
  billing_period_start  timestamptz,
  billing_period_end    timestamptz,
  receipt_url           text,
  created_at            timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'billing_history_status_check'
  ) then
    alter table public.billing_history add constraint billing_history_status_check
      check (status in ('paid', 'failed', 'refunded', 'pending'));
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'billing_history_amount_check'
  ) then
    -- Zero is legitimate (a fully discounted period); negative is not — a
    -- refund is its own status, not a negative charge.
    alter table public.billing_history add constraint billing_history_amount_check
      check (amount >= 0);
  end if;
end $$;

-- §16, criterion 7 — a replayed webhook must not write a second invoice row.
-- Partial, because a provider may deliver a payment with no invoice id.
create unique index if not exists billing_history_invoice_uidx
  on public.billing_history (provider, provider_invoice_id)
  where provider_invoice_id is not null;

-- The billing history page: newest first, per user.
create index if not exists billing_history_user_created_idx
  on public.billing_history (user_id, created_at desc);

-- -----------------------------------------------------------------------------
-- updated_at
-- -----------------------------------------------------------------------------

drop trigger if exists billing_customers_set_updated_at on public.billing_customers;
create trigger billing_customers_set_updated_at
  before update on public.billing_customers
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- RLS (criterion 18, criterion 22)
--
-- SELECT own rows, and no write policy of any kind. Billing rows are written
-- by the webhook handler using the secret key, after a verified signature —
-- there is no client-reachable path, and criterion 22 asks for the database to
-- be the thing that refuses rather than the application.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['billing_customers', 'billing_history'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('drop policy if exists %I_select_own on public.%I', t, t);
    execute format(
      'create policy %I_select_own on public.%I for select to authenticated
       using (user_id = (select auth.uid()))', t, t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- §11 — billing_customers holds a provider's customer id. It is not secret,
-- but it is also nothing a browser needs: the mapping is only ever used
-- server-side to turn a webhook into a user. Withheld on that basis.
revoke select on public.billing_customers from authenticated;
drop policy if exists billing_customers_select_own on public.billing_customers;


-- ======================================================================
-- 20260914000900_phase12_ai_assistant.sql
-- ======================================================================

-- =============================================================================
-- Phase 12 — AI Financial Assistant: conversations, messages, provider logs
--
-- The storage half. Nothing here knows which model answers a question: §7
-- forbids hardcoding model identifiers through business logic, so `provider`
-- and `model` are plain text columns written by whichever adapter ran.
--
-- ## What is deliberately NOT stored
--
-- §18: not whole query result payloads, not raw OCR text, not account numbers.
-- `ai_messages.query_metadata` holds the intent and the resolved date range —
-- enough to show why an answer said what it said, and to investigate a bad
-- one, without keeping a second copy of the user's finances in a jsonb column
-- that no retention policy covers.
--
-- §94: the audit log never receives prompt text either. That rule lives in
-- `lib/auth/audit.ts` callers; this file is where the *conversation* copy
-- lives, and it is scoped to the user who wrote it.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- ai_conversations (§17)
-- -----------------------------------------------------------------------------

create table if not exists public.ai_conversations (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  title       text,
  is_archived boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- The list page: a user's live threads, most recently used first.
create index if not exists ai_conversations_user_idx
  on public.ai_conversations (user_id, updated_at desc)
  where is_archived = false;

-- -----------------------------------------------------------------------------
-- ai_messages (§17, §18)
--
-- `role` is constrained rather than free text because the whole grounding
-- story depends on being able to tell whose words a row holds. A forged
-- 'assistant' row is the application appearing to have said something it never
-- said — which is why there is no client write path to this table at all.
-- -----------------------------------------------------------------------------

create table if not exists public.ai_messages (
  id              uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.ai_conversations (id) on delete cascade,
  user_id         uuid not null references auth.users (id) on delete cascade,
  role            text not null,
  content         text not null,
  -- Null for a user turn, and for an assistant turn that never resolved to a
  -- supported intent (a clarification, or a refusal).
  intent          text,
  query_metadata  jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ai_messages_role_check') then
    alter table public.ai_messages add constraint ai_messages_role_check
      check (role in ('user', 'assistant'));
  end if;

  -- §44 — the same 2000-character ceiling the action enforces, stated here too
  -- so a future caller that forgets cannot write an unbounded prompt.
  if not exists (select 1 from pg_constraint where conname = 'ai_messages_content_length_check') then
    alter table public.ai_messages add constraint ai_messages_content_length_check
      check (char_length(content) <= 8000);
  end if;
end $$;

-- Reading one thread in order.
create index if not exists ai_messages_conversation_idx
  on public.ai_messages (conversation_id, created_at);

-- -----------------------------------------------------------------------------
-- ai_usage_logs (§54, §55)
--
-- Provider calls, for cost analysis. Deliberately NOT the quota unit: one
-- question is one `ai_queries` row in `usage_records` even when it makes two
-- provider calls (intent parsing, then explanation). The gap between the two
-- counts is what the cost-per-question number is made of.
--
-- `input_units` / `output_units` rather than `input_tokens`: a future provider
-- may not bill in tokens, and §40 of Phase 09 is that the domain must not take
-- on one provider's vocabulary.
-- -----------------------------------------------------------------------------

create table if not exists public.ai_usage_logs (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  conversation_id uuid references public.ai_conversations (id) on delete set null,
  intent          text,
  provider        text not null,
  model           text not null,
  -- The call this row describes: parsing a question, or explaining figures.
  call_type       text not null,
  input_units     integer not null default 0,
  output_units    integer not null default 0,
  duration_ms     integer not null default 0,
  status          text not null,
  error_code      text,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ai_usage_logs_status_check') then
    alter table public.ai_usage_logs add constraint ai_usage_logs_status_check
      check (status in ('succeeded', 'failed', 'timeout', 'rejected'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'ai_usage_logs_call_type_check') then
    alter table public.ai_usage_logs add constraint ai_usage_logs_call_type_check
      check (call_type in ('intent', 'explanation'));
  end if;
end $$;

-- §55 — cost per user per period, and the failure rate behind §30's provider
-- health panel.
create index if not exists ai_usage_logs_user_created_idx
  on public.ai_usage_logs (user_id, created_at desc);

create index if not exists ai_usage_logs_failures_idx
  on public.ai_usage_logs (created_at desc)
  where status <> 'succeeded';

-- -----------------------------------------------------------------------------
-- updated_at
-- -----------------------------------------------------------------------------

drop trigger if exists ai_conversations_set_updated_at on public.ai_conversations;
create trigger ai_conversations_set_updated_at
  before update on public.ai_conversations
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- RLS (criterion 19, criterion 20)
--
-- Client reads its own rows; every write goes through a server action (master
-- plan §33), which is the pattern every table since Phase 02 has used.
--
-- For `ai_messages` that rule carries extra weight and is worth naming: a
-- client able to insert an 'assistant' row could forge the system's own words
-- into a user's history — a grounded answer that HelloPera never produced,
-- indistinguishable afterwards from one it did. Criterion 19 asks for exactly
-- this, and the database is what refuses.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['ai_conversations', 'ai_messages', 'ai_usage_logs'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated
       using (user_id = (select auth.uid()))', t || '_select_own', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- §55 — cost analysis is operational, not something a user reads about
-- themselves, and it names the provider and model HelloPera uses. No browser
-- needs it; withheld on that basis, the same way `billing_customers` is.
revoke select on public.ai_usage_logs from authenticated;
drop policy if exists ai_usage_logs_select_own on public.ai_usage_logs;


-- ======================================================================
-- 20260914001000_phase13_admin_operations.sql
-- ======================================================================

-- =============================================================================
-- Phase 13 — Admin and Operations: support notes, overrides, adjustments
--
-- Three tables that exist for one reason, stated in DATA-MODEL.md: **to avoid
-- falsifying primary records.**
--
-- Promotional Premium is an `entitlement_overrides` row, not a subscription row
-- invented to look like a purchase. A goodwill usage credit is a
-- `usage_adjustments` row, not an edit to `usage_records`. In both cases the
-- alternative — writing the lie into the primary table — is cheaper today and
-- unrecoverable later: nothing afterwards can tell an operator's kindness apart
-- from a real payment or a real scan.
--
-- ## Access
--
-- These are OPERATIONAL tables. Unlike every user-owned table since Phase 02,
-- they get no SELECT-own policy, because none of these rows belongs to the user
-- they are about: a support note is written by an admin about someone, and
-- letting that someone read it changes what admins are willing to write down.
-- RLS is enabled and forced, everything is revoked, and no policy exists — so
-- the browser role cannot reach them at all, whatever a future query attempts.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- admin_support_notes (§16)
-- -----------------------------------------------------------------------------

create table if not exists public.admin_support_notes (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  -- `set null`, not cascade: deleting a departed admin's account must not erase
  -- the support history of the users they helped.
  admin_user_id uuid references auth.users (id) on delete set null,
  note          text not null,
  created_at    timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'admin_support_notes_note_check'
  ) then
    alter table public.admin_support_notes add constraint admin_support_notes_note_check
      check (char_length(btrim(note)) between 1 and 4000);
  end if;
end $$;

create index if not exists admin_support_notes_user_idx
  on public.admin_support_notes (user_id, created_at desc);

-- -----------------------------------------------------------------------------
-- entitlement_overrides (§19)
--
-- A per-user override of one entitlement key, for a window of time.
--
-- `value_json` deliberately matches `plan_entitlements.value_json`, because
-- `resolveEntitlements()` already reduces rows of that exact shape into a map
-- where a later row wins. An override in effect is therefore appended after the
-- plan's rows and needs no second resolution path — one place decides what a
-- user is entitled to, which is what stops the two answers drifting.
-- -----------------------------------------------------------------------------

create table if not exists public.entitlement_overrides (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  entitlement_key text not null,
  value_json      jsonb not null,
  -- §54 — never optional. An override with no reason is indistinguishable from
  -- a mistake six months later.
  reason          text not null,
  starts_at       timestamptz not null default now(),
  -- Null means open-ended. Allowed, but the admin UI defaults to a date:
  -- a promotion nobody remembers granting is a promotion nobody ends.
  ends_at         timestamptz,
  created_by      uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'entitlement_overrides_key_check'
  ) then
    -- The same keys `plan_entitlements` constrains. A typo here would resolve
    -- to nothing and look like the override silently failing.
    alter table public.entitlement_overrides add constraint entitlement_overrides_key_check
      check (entitlement_key in (
        'ocr_monthly_limit', 'ai_monthly_limit', 'advanced_analytics',
        'forecast_horizon_days', 'export_enabled', 'ads_shown',
        'document_retention_days', 'max_documents', 'max_accounts',
        'premium_support'
      ));
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'entitlement_overrides_window_check'
  ) then
    alter table public.entitlement_overrides add constraint entitlement_overrides_window_check
      check (ends_at is null or ends_at > starts_at);
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'entitlement_overrides_reason_check'
  ) then
    alter table public.entitlement_overrides add constraint entitlement_overrides_reason_check
      check (char_length(btrim(reason)) between 3 and 500);
  end if;
end $$;

-- The lookup `getEffectivePlan` performs on every request: this user's
-- overrides that are in effect now.
create index if not exists entitlement_overrides_active_idx
  on public.entitlement_overrides (user_id, starts_at, ends_at);

-- -----------------------------------------------------------------------------
-- usage_adjustments (§23)
--
-- A signed credit or debit against a metered feature, recorded separately from
-- the usage it adjusts. §32 of Phase 09 says usage already spent is not erased;
-- this is how a refund of one is expressed without contradicting that.
-- -----------------------------------------------------------------------------

create table if not exists public.usage_adjustments (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  feature_key     text not null,
  -- Signed. Negative gives a user back a scan that HelloPera's own failure
  -- consumed; positive exists for the rarer correction in the other direction.
  quantity_delta  integer not null,
  reason          text not null,
  created_by      uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now()
);

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'usage_adjustments_feature_check'
  ) then
    alter table public.usage_adjustments add constraint usage_adjustments_feature_check
      check (feature_key in ('ocr_jobs', 'ai_queries', 'document_uploads', 'exports'));
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'usage_adjustments_delta_check'
  ) then
    -- Zero is not an adjustment, and a bounded magnitude turns a slipped digit
    -- into a refusal rather than a year of free scans.
    alter table public.usage_adjustments add constraint usage_adjustments_delta_check
      check (quantity_delta <> 0 and abs(quantity_delta) <= 1000);
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'usage_adjustments_reason_check'
  ) then
    alter table public.usage_adjustments add constraint usage_adjustments_reason_check
      check (char_length(btrim(reason)) between 3 and 500);
  end if;
end $$;

create index if not exists usage_adjustments_user_idx
  on public.usage_adjustments (user_id, created_at desc);

-- -----------------------------------------------------------------------------
-- RLS (criterion 19, criterion 21)
--
-- Enabled, forced, everything revoked, and NO policy on any of the three. A
-- table with RLS on and no policy is readable by nobody through the browser
-- role, which is the intent — these are operational records about users, not
-- records belonging to them.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array[
    'admin_support_notes', 'entitlement_overrides', 'usage_adjustments'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- §14 — a user can never make themselves an admin
--
-- Today this trigger cannot fire from a browser: `authenticated` holds only
-- SELECT on `profiles` (Phase 01), so there is no client UPDATE to intercept.
-- It is written anyway, and the reason is worth stating plainly rather than
-- overselling.
--
-- "No write path exists" is a property of the *grants*, and grants change. The
-- obvious future change — letting people edit their own name without a round
-- trip through a server action — is one `grant update` away, and it would
-- silently hand every user `role` and `status` as well. This trigger is what
-- makes that a refusal instead of a privilege-escalation bug, and it costs one
-- function.
--
-- The service role is exempt (`auth.uid()` is null for it): admin actions run
-- through it, after `requireAdminAction()` has checked the caller.
-- -----------------------------------------------------------------------------

create or replace function public.reject_self_privilege_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Trusted server paths only. `auth.uid()` is null for the service role.
  if (select auth.uid()) is null then
    return new;
  end if;

  if new.role is distinct from old.role then
    raise exception 'role cannot be changed from the client'
      using errcode = 'insufficient_privilege';
  end if;

  if new.status is distinct from old.status then
    raise exception 'status cannot be changed from the client'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end $$;

revoke all on function public.reject_self_privilege_change() from public;

drop trigger if exists profiles_reject_self_privilege_change on public.profiles;
create trigger profiles_reject_self_privilege_change
  before update on public.profiles
  for each row execute function public.reject_self_privilege_change();


-- ======================================================================
-- 20260915000100_phase14_financial_integrity.sql
-- ======================================================================

-- =============================================================================
-- Phase 14 — Financial integrity: detect without repairing
--
-- §65: "It should report mismatches. **Do not silently modify data without
-- controlled repair.**"
--
-- `check_balance_integrity()` as Phase 02 shipped it cannot satisfy that,
-- because it calls `recalculate_account_balance()` — whose last statement is
-- `update public.accounts set current_balance = ...`. Its own comment said so
-- plainly: "Recalculating repairs as it reads, so run it to both detect and fix
-- drift."
--
-- That was a reasonable thing to ship in Phase 02, when nothing was watching.
-- It is the wrong thing now, and the reason is worth stating: a checker that
-- repairs destroys the evidence of the drift it found. Nobody can then answer
-- how often it happens, to which accounts, or after which operation — so a real
-- bug in the balance engine looks exactly like a system that is working. A
-- finance application that silently self-corrects is one where the most
-- important class of defect is invisible by construction.
--
-- So the arithmetic is split from the write:
--
--   derive_account_balance()      the §34 matrix. Returns a number. Writes
--                                 nothing.
--   recalculate_account_balance() calls derive, then writes. Every existing
--                                 write path is unchanged.
--   check_balance_integrity()     calls derive. Reports. Never writes.
--
-- One copy of the matrix instead of two, which also means
-- `lib/finance/sql-parity.test.ts` guards one thing rather than needing to
-- guard both.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- derive_account_balance (§64)
--
-- The PHASE-02 §34 balance-effect matrix, moved here verbatim from
-- `recalculate_account_balance`. `accounts.opening_balance` is deliberately
-- excluded: an opening balance enters the ledger as an `opening_balance`
-- transaction, and counting the column as well would double it.
-- -----------------------------------------------------------------------------

create or replace function public.derive_account_balance(p_account_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_nature  text;
  v_balance numeric(18, 2);
begin
  select nature into v_nature from public.accounts where id = p_account_id;
  if v_nature is null then
    raise exception 'No account %', p_account_id;
  end if;

  select coalesce(sum(
    case
      -- as SOURCE
      when t.source_account_id = p_account_id then
        case t.type
          when 'expense'    then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'transfer'   then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'adjustment' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      -- as DESTINATION
      when t.destination_account_id = p_account_id then
        case t.type
          when 'income'          then case when v_nature = 'asset' then t.amount else 0 end
          when 'refund'          then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'transfer'        then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'opening_balance' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      else 0
    end
  ), 0)
  into v_balance
  from public.transactions t
  where t.status = 'confirmed'
    and (t.source_account_id = p_account_id or t.destination_account_id = p_account_id);

  return v_balance;
end;
$$;

comment on function public.derive_account_balance(uuid) is
  'The PHASE-02 section 34 matrix. Returns the balance implied by confirmed transactions. Writes nothing.';

-- -----------------------------------------------------------------------------
-- recalculate_account_balance — now a thin write over derive
--
-- Behaviour is identical for every caller: the transaction RPCs still call this
-- after a write to refresh the cache. What changed is that the arithmetic lives
-- in one place.
-- -----------------------------------------------------------------------------

create or replace function public.recalculate_account_balance(p_account_id uuid)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_balance numeric(18, 2);
begin
  v_balance := public.derive_account_balance(p_account_id);
  update public.accounts set current_balance = v_balance where id = p_account_id;
  return v_balance;
end;
$$;

comment on function public.recalculate_account_balance(uuid) is
  'Derives via derive_account_balance and writes the cache. Called after every balance-affecting write.';

-- -----------------------------------------------------------------------------
-- check_balance_integrity — now genuinely a check (§64, §65)
-- -----------------------------------------------------------------------------

create or replace function public.check_balance_integrity(p_user_id uuid)
returns table (account_id uuid, account_name text, cached numeric, derived numeric)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
  select a.id, a.name, a.current_balance, public.derive_account_balance(a.id)
  from public.accounts a
  where a.user_id = p_user_id;
end;
$$;

comment on function public.check_balance_integrity(uuid) is
  'Reports cached vs derived balance per account. Read-only: repair is a separate audited admin action (PHASE-14 section 66).';

-- -----------------------------------------------------------------------------
-- check_financial_integrity (§64)
--
-- Every §64 check in one call, returning a uniform row shape so a caller can
-- render them without knowing what each one means.
--
-- `p_user_id` null means every user — the scheduled job's case. Scoped for an
-- admin looking at one account.
-- -----------------------------------------------------------------------------

create or replace function public.check_financial_integrity(p_user_id uuid default null)
returns table (
  check_name  text,
  user_id     uuid,
  entity_type text,
  entity_id   uuid,
  detail      text,
  expected    numeric,
  actual      numeric
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  -- 1. Cached balance vs the transactions that imply it.
  return query
  select 'account_balance'::text, a.user_id, 'account'::text, a.id,
         a.name, public.derive_account_balance(a.id), a.current_balance
  from public.accounts a
  where (p_user_id is null or a.user_id = p_user_id)
    and a.current_balance is distinct from public.derive_account_balance(a.id);

  -- 2. A bill cannot have more applied to it than it is for. Over-allocation
  --    means a payment was linked twice, or a bill's amount was reduced after
  --    payments were recorded against it.
  return query
  select 'bill_over_allocated'::text, b.user_id, 'bill'::text, b.id,
         b.provider_name, b.amount, sum(p.amount_applied)
  from public.bills b
  join public.bill_payments p on p.bill_id = b.id
  where (p_user_id is null or b.user_id = p_user_id)
  group by b.id, b.user_id, b.provider_name, b.amount
  having sum(p.amount_applied) > b.amount;

  -- 3. Same for money owed to the user.
  return query
  select 'receivable_over_allocated'::text, r.user_id, 'receivable'::text, r.id,
         r.party_name, r.amount, sum(p.amount_applied)
  from public.receivables r
  join public.receivable_payments p on p.receivable_id = r.id
  where (p_user_id is null or r.user_id = p_user_id)
  group by r.id, r.user_id, r.party_name, r.amount
  having sum(p.amount_applied) > r.amount;

  -- 4. And for expected income.
  return query
  select 'expected_income_over_allocated'::text, e.user_id, 'expected_income'::text, e.id,
         e.source_name, e.amount, sum(p.amount_applied)
  from public.expected_income e
  join public.expected_income_receipts p on p.expected_income_id = e.id
  where (p_user_id is null or e.user_id = p_user_id)
  group by e.id, e.user_id, e.source_name, e.amount
  having sum(p.amount_applied) > e.amount;

  -- 5. A payment link whose obligation says it is fully paid but whose applied
  --    total says otherwise. The status is a cache of the sum, and a status
  --    that disagrees with its own evidence is how a paid bill reappears.
  return query
  select 'bill_status_mismatch'::text, b.user_id, 'bill'::text, b.id,
         b.provider_name || ' is marked ' || b.status, b.amount,
         coalesce((select sum(p.amount_applied) from public.bill_payments p where p.bill_id = b.id), 0)
  from public.bills b
  where (p_user_id is null or b.user_id = p_user_id)
    and b.status = 'paid'
    and coalesce((select sum(p.amount_applied) from public.bill_payments p where p.bill_id = b.id), 0) < b.amount;

  -- 6. Document links point at a uuid in another table with no foreign key to
  --    enforce it (`document_links.entity_id` is deliberately polymorphic), so
  --    nothing but this notices when the target is gone.
  return query
  select 'orphaned_document_link'::text, l.user_id, 'document_link'::text, l.id,
         'points at a missing ' || l.entity_type, null::numeric, null::numeric
  from public.document_links l
  where (p_user_id is null or l.user_id = p_user_id)
    and not exists (
      select 1 from public.transactions t
      where l.entity_type = 'transaction' and t.id = l.entity_id
      union all
      select 1 from public.bills b
      where l.entity_type = 'bill' and b.id = l.entity_id
      union all
      select 1 from public.receivables r
      where l.entity_type = 'receivable' and r.id = l.entity_id
      union all
      select 1 from public.expected_income e
      where l.entity_type = 'expected_income' and e.id = l.entity_id
    );

  -- 7. A subscription whose stored status contradicts its own dates. PHASE-11
  --    §29 makes the read path correct without this ever running, so a hit here
  --    means the reconciliation job is not running rather than that anyone lost
  --    access.
  return query
  select 'subscription_stale'::text, s.user_id, 'subscription'::text, s.id,
         'status ' || s.status || ' but the period ended', null::numeric, null::numeric
  from public.subscriptions s
  where (p_user_id is null or s.user_id = p_user_id)
    and (
      (s.status = 'grace'     and s.grace_period_end   is not null and s.grace_period_end   <= now())
      or
      (s.status = 'cancelled' and s.current_period_end is not null and s.current_period_end <= now())
    );
end;
$$;

comment on function public.check_financial_integrity(uuid) is
  'PHASE-14 section 64. Reports every integrity mismatch. Writes nothing, ever.';

-- -----------------------------------------------------------------------------
-- repair_account_balance (§66)
--
-- The controlled repair §65 requires. Narrow: one account. Deterministic: the
-- same derivation the check uses. It is called only from the admin action,
-- which supplies a reason and writes the audit row — this function deliberately
-- does neither, because a repair that audits itself would let a future caller
-- skip the reason and still look accounted for.
-- -----------------------------------------------------------------------------

create or replace function public.repair_account_balance(p_account_id uuid)
returns table (previous numeric, corrected numeric)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_previous numeric(18, 2);
  v_corrected numeric(18, 2);
begin
  select current_balance into v_previous from public.accounts where id = p_account_id;
  if v_previous is null then
    raise exception 'No account %', p_account_id;
  end if;

  v_corrected := public.recalculate_account_balance(p_account_id);
  return query select v_previous, v_corrected;
end;
$$;

comment on function public.repair_account_balance(uuid) is
  'PHASE-14 section 66. Narrow, deterministic repair of one account. The caller audits.';

-- -----------------------------------------------------------------------------
-- run_financial_integrity_check (§65)
--
-- The scheduled reporter. Takes the advisory lock, records a `job_runs` row,
-- counts mismatches by check, and finishes. It repairs nothing — the whole
-- point is that a human sees the number and decides.
--
-- The lock is taken, held and released within this one call: a begin/finish
-- split leaks the lock under Supavisor, where the next statement may arrive on
-- a different session.
-- -----------------------------------------------------------------------------

create or replace function public.run_financial_integrity_check()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type text := 'financial_integrity_check';
  v_job_id   uuid;
  v_started  timestamptz := clock_timestamp();
  v_counts   jsonb;
  v_total    integer := 0;
begin
  if not pg_try_advisory_lock(hashtext(v_job_type)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status)
  values (v_job_type, 'running')
  returning id into v_job_id;

  begin
    select coalesce(jsonb_object_agg(check_name, n), '{}'::jsonb), coalesce(sum(n), 0)
    into v_counts, v_total
    from (
      select check_name, count(*)::integer as n
      from public.check_financial_integrity(null)
      group by check_name
    ) grouped;

    update public.job_runs
    set status       = 'succeeded',
        completed_at = now(),
        duration_ms  = (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
        -- The findings live here rather than in a table of their own: they are
        -- derived, so a stored copy would go stale the moment anything is
        -- fixed, and a stale integrity report is worse than none.
        metadata     = jsonb_build_object('mismatches', v_total, 'by_check', v_counts)
    where id = v_job_id;

  exception when others then
    update public.job_runs
    set status       = 'failed',
        completed_at = now(),
        duration_ms  = (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
        error_code   = sqlstate,
        metadata     = jsonb_build_object('error', left(sqlerrm, 500))
    where id = v_job_id;

    perform pg_advisory_unlock(hashtext(v_job_type));
    raise;
  end;

  perform pg_advisory_unlock(hashtext(v_job_type));
  return jsonb_build_object('mismatches', v_total, 'by_check', v_counts);
end;
$$;

-- -----------------------------------------------------------------------------
-- Grants — §71, and the Phase 07 lesson
--
-- `revoke ... from anon, authenticated` is a NO-OP for a function: PUBLIC holds
-- EXECUTE by default and those roles inherit it. Revoking from PUBLIC is what
-- actually closes the door. This is the same mistake 20260914000200 fixed
-- across sixteen functions.
-- -----------------------------------------------------------------------------

revoke all on function public.derive_account_balance(uuid) from public;
revoke all on function public.check_financial_integrity(uuid) from public;
revoke all on function public.repair_account_balance(uuid) from public;
revoke all on function public.run_financial_integrity_check() from public;

grant execute on function public.derive_account_balance(uuid) to service_role;
grant execute on function public.check_financial_integrity(uuid) to service_role;
grant execute on function public.repair_account_balance(uuid) to service_role;
grant execute on function public.run_financial_integrity_check() to service_role;

-- -----------------------------------------------------------------------------
-- Schedule (§65) — daily, guarded the same way Phase 07's is.
-- -----------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;

  if exists (select 1 from cron.job where jobname = 'financial_integrity_check') then
    perform cron.unschedule('financial_integrity_check');
  end if;

  -- Daily rather than hourly: drift is not urgent, and this scans every
  -- account for every user. 04:40 UTC is 12:40pm in Manila — deliberately not
  -- on the hour, where it would contend with the generation job.
  perform cron.schedule(
    'financial_integrity_check',
    '40 4 * * *',
    $cron$ select public.run_financial_integrity_check() $cron$
  );

  raise notice 'pg_cron: financial_integrity_check scheduled daily';
exception when others then
  raise warning 'pg_cron unavailable (%): run public.run_financial_integrity_check() from the admin screen instead.', sqlerrm;
end $$;


-- ======================================================================
-- 20260915000200_phase14_ops_flags.sql
-- ======================================================================

-- =============================================================================
-- Phase 14 — operational flags
--
-- `financial_writes_enabled` (§23) and `retention_enabled` (§73).
--
-- Note the asymmetry in their defaults, which is deliberate:
--
--   financial_writes_enabled  ships ON.  It is a freeze, and a freeze that is
--                                        on by default means a fresh deployment
--                                        silently refuses every transaction.
--   retention_enabled         ships OFF. It deletes things, and §73 says the
--                                        policy must match the privacy page.
--                                        No periods have been decided, so
--                                        nothing should be deleting yet.
--
-- `maintenance_mode` is deliberately NOT here. It is an environment variable,
-- because the usual reason to enter maintenance is that this database is the
-- problem, and a switch stored in the thing it protects is unreadable exactly
-- when it is needed. See lib/ops/kill-switches.ts.
--
-- Idempotent.
-- =============================================================================

insert into public.feature_flags (key, enabled, config)
values
  (
    'financial_writes_enabled',
    true,
    '{"note": "PHASE-14 section 23. Turn OFF to freeze the ledger: records stay readable, nothing can be written."}'::jsonb
  ),
  (
    'retention_enabled',
    false,
    '{"note": "PHASE-14 section 73. Turn ON only once retention periods are decided and match the privacy page."}'::jsonb
  )
on conflict (key) do nothing;


-- ======================================================================
-- 20260915000300_phase14_retention.sql
-- ======================================================================

-- =============================================================================
-- Phase 14 — retention cleanup, built and switched off
--
-- §73: "Define actual retention for: documents, OCR raw text, AI
-- conversations, notifications, logs, audit records, deleted accounts. **Policy
-- must match Privacy page.**"
--
-- No policy exists yet, and PHASE-12 §19 already says retention must not be
-- destructive without one. So these functions are written, tested and
-- **disabled**: every one of them refuses to run unless `retention_enabled` is
-- on, and that flag ships off.
--
-- Periods are parameters with conservative defaults rather than decisions.
-- Inventing a number here would put the application in contradiction with the
-- published privacy page, which is worse than deleting nothing — the page is a
-- promise, and this is the code that would break it.
--
-- ## What each one would delete
--
-- Recorded here so the decision can be made against the privacy page rather
-- than in the abstract, and repeated in LAUNCH-CHECKLIST.md §15.
--
--   expired_notifications   notifications past `expires_at`. Least sensitive:
--                           they are derived from bills and balances that
--                           still exist.
--   ocr_text                `ocr_results.raw_text` only. The extracted FIELDS
--                           and the document survive — this drops the verbatim
--                           transcription, which is the most sensitive artefact
--                           OCR produces and the least useful to keep.
--   inactive_push           subscriptions that have failed repeatedly. Not user
--                           data in any meaningful sense; a dead device.
--
-- Documents themselves are deliberately NOT here. `document_retention_days` is
-- an entitlement users are sold on, so expiring their receipts is a product
-- decision, not an operational one.
--
-- Idempotent.
-- =============================================================================

create or replace function public.retention_is_enabled()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select enabled from public.feature_flags where key = 'retention_enabled'), false)
$$;

comment on function public.retention_is_enabled() is
  'PHASE-14 section 73. Ships false. Every retention job checks this first.';

-- -----------------------------------------------------------------------------
-- run_retention_cleanup (§74, §75, §76, §77)
--
-- One function rather than three, so there is one place the flag is checked and
-- one `job_runs` row to read. Each step reports what it removed; a step that
-- removes nothing is normal, not an error.
--
-- Lock taken, held and released in this one call — a begin/finish split leaks
-- it under Supavisor, where the next statement may land on another session.
-- -----------------------------------------------------------------------------

create or replace function public.run_retention_cleanup(
  p_notification_days integer default 30,
  p_ocr_text_days     integer default 365,
  p_push_failures     integer default 10
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type text := 'retention_cleanup';
  v_job_id   uuid;
  v_started  timestamptz := clock_timestamp();
  v_notifications integer := 0;
  v_ocr_text      integer := 0;
  v_push          integer := 0;
  v_n             integer;
begin
  -- The switch, before anything else. A disabled job is not a failure: it
  -- returns and says so, and the scheduler can keep firing harmlessly until
  -- someone decides the policy.
  if not public.retention_is_enabled() then
    return jsonb_build_object('skipped', true, 'reason', 'retention_disabled');
  end if;

  if not pg_try_advisory_lock(hashtext(v_job_type)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status)
  values (v_job_type, 'running')
  returning id into v_job_id;

  begin
    -- 1. Notifications past their own expiry, plus a grace period.
    delete from public.notifications
    where expires_at is not null
      and expires_at < now() - make_interval(days => p_notification_days);
    get diagnostics v_n = row_count;
    v_notifications := v_n;

    -- 2. The verbatim OCR transcription, nulled rather than deleted: the row
    --    records that a document was read, when, and by which provider, and
    --    losing that would make the job history unreadable. It is the TEXT that
    --    is sensitive.
    update public.ocr_results
    set raw_text = null
    where raw_text is not null
      and created_at < now() - make_interval(days => p_ocr_text_days);
    get diagnostics v_n = row_count;
    v_ocr_text := v_n;

    -- 3. Push subscriptions that have failed enough times to be dead devices.
    delete from public.push_subscriptions
    where failure_count >= p_push_failures
      and is_active = false;
    get diagnostics v_n = row_count;
    v_push := v_n;

    update public.job_runs
    set status       = 'succeeded',
        completed_at = now(),
        duration_ms  = (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
        metadata     = jsonb_build_object(
                         'notifications_deleted', v_notifications,
                         'ocr_text_cleared',      v_ocr_text,
                         'push_subscriptions_deleted', v_push
                       )
    where id = v_job_id;

  exception when others then
    update public.job_runs
    set status       = 'failed',
        completed_at = now(),
        duration_ms  = (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
        error_code   = sqlstate,
        metadata     = jsonb_build_object('error', left(sqlerrm, 500))
    where id = v_job_id;

    perform pg_advisory_unlock(hashtext(v_job_type));
    raise;
  end;

  perform pg_advisory_unlock(hashtext(v_job_type));

  return jsonb_build_object(
    'notifications_deleted',      v_notifications,
    'ocr_text_cleared',           v_ocr_text,
    'push_subscriptions_deleted', v_push
  );
end;
$$;

-- PUBLIC holds EXECUTE by default; revoking from anon/authenticated is a no-op.
revoke all on function public.retention_is_enabled() from public;
revoke all on function public.run_retention_cleanup(integer, integer, integer) from public;
grant execute on function public.retention_is_enabled() to service_role;
grant execute on function public.run_retention_cleanup(integer, integer, integer) to service_role;

-- -----------------------------------------------------------------------------
-- Schedule — the job runs daily and does nothing until the flag is on.
--
-- Scheduling a disabled job is deliberate: it means turning retention on is one
-- flag in the admin UI rather than a migration, and the schedule has already
-- been exercised by then.
-- -----------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;

  if exists (select 1 from cron.job where jobname = 'retention_cleanup') then
    perform cron.unschedule('retention_cleanup');
  end if;

  perform cron.schedule(
    'retention_cleanup',
    '50 4 * * *',
    $cron$ select public.run_retention_cleanup() $cron$
  );

  raise notice 'pg_cron: retention_cleanup scheduled daily (disabled until retention_enabled is on)';
exception when others then
  raise warning 'pg_cron unavailable (%): retention cleanup will not run automatically.', sqlerrm;
end $$;


-- ======================================================================
-- 20260921000100_provider_features_default_off.sql
-- ======================================================================

-- Provider-backed features stay dark until credentials and delivery have been
-- verified in a production-like environment. The application now consults
-- both switches, so these rows are operational kill switches rather than
-- descriptive metadata.

update public.feature_flags
set enabled = false,
    config = config || '{"requires_provider_configuration": true}'::jsonb,
    updated_at = now()
where key in ('ocr_enabled', 'push_enabled');


-- ======================================================================
-- 20260923000100_launch_integrity.sql
-- ======================================================================

-- Launch integrity: retry-safe payments and validated recurring settlement.
create table if not exists public.payment_requests (
  user_id uuid not null references auth.users(id) on delete cascade,
  request_id uuid not null,
  payload jsonb not null,
  transaction_id uuid not null references public.transactions(id),
  allocation_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (user_id, request_id)
);
alter table public.payment_requests enable row level security;
revoke all on public.payment_requests from public, anon, authenticated;
grant all on public.payment_requests to service_role;

create or replace function public.record_obligation_payment(
  p_user_id uuid, p_request_id uuid, p_kind text, p_obligation_id uuid,
  p_amount numeric, p_account_id uuid default null,
  p_date date default null, p_transaction_id uuid default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_payload jsonb; v_previous public.payment_requests%rowtype;
  v_currency text; v_tx uuid; v_allocation uuid; v_type text;
begin
  if p_request_id is null or p_kind is null or p_kind not in ('bill','receivable','expected_income') then
    raise exception 'INVALID_PAYMENT_REQUEST';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount <> round(p_amount,2) then raise exception 'AMOUNT_NOT_POSITIVE'; end if;
  -- One user's payment retries serialize, including concurrent identical requests.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 731));
  if not exists(select 1 from public.profiles where id=p_user_id and status='active') then
    raise exception 'USER_UNAVAILABLE';
  end if;
  v_payload := jsonb_build_object('kind',p_kind,'obligation',p_obligation_id,
    'amount',p_amount,'account',p_account_id,'date',p_date,'transaction',p_transaction_id);
  select * into v_previous from public.payment_requests
    where user_id=p_user_id and request_id=p_request_id;
  if found then
    if v_previous.payload <> v_payload then raise exception 'REQUEST_ALREADY_USED'; end if;
    return jsonb_build_object('transaction_id',v_previous.transaction_id,'allocation_id',v_previous.allocation_id);
  end if;
  -- Existing transaction first: same lock order as void_transaction.
  if p_transaction_id is not null then
    select id, type into v_tx,v_type from public.transactions
      where id=p_transaction_id and user_id=p_user_id and status='confirmed' for update;
    if v_tx is null then raise exception 'TRANSACTION_NOT_CONFIRMED'; end if;
    if v_type <> (case when p_kind='bill' then 'expense' else 'income' end) then
      raise exception 'TRANSACTION_DIRECTION_MISMATCH';
    end if;
  end if;
  if p_kind='bill' then
    select currency_code into v_currency from public.bills where id=p_obligation_id and user_id=p_user_id for update;
  elsif p_kind='receivable' then
    select currency_code into v_currency from public.receivables where id=p_obligation_id and user_id=p_user_id for update;
  else
    select currency_code into v_currency from public.expected_income where id=p_obligation_id and user_id=p_user_id for update;
  end if;
  if v_currency is null then raise exception 'OBLIGATION_NOT_FOUND'; end if;
  if p_transaction_id is null then
    if p_account_id is null or p_date is null then raise exception 'INVALID_PAYMENT_REQUEST'; end if;
    v_tx := public.create_transaction(p_user_id,
      case when p_kind='bill' then 'expense' else 'income' end,
      p_amount,v_currency,p_date,
      case when p_kind='bill' then p_account_id else null end,
      case when p_kind<>'bill' then p_account_id else null end);
  end if;
  v_allocation := public.allocate_payment(p_user_id,p_kind,p_obligation_id,v_tx,p_amount);
  insert into public.payment_requests(user_id,request_id,payload,transaction_id,allocation_id)
    values(p_user_id,p_request_id,v_payload,v_tx,v_allocation);
  return jsonb_build_object('transaction_id',v_tx,'allocation_id',v_allocation);
end $$;
revoke all on function public.record_obligation_payment(uuid,uuid,text,uuid,numeric,uuid,date,uuid) from public, anon, authenticated;
grant execute on function public.record_obligation_payment(uuid,uuid,text,uuid,numeric,uuid,date,uuid) to service_role;

create or replace function public.fulfill_expected_event(p_user_id uuid,p_event_id uuid,p_transaction_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_tx public.transactions%rowtype; v_event public.expected_events%rowtype;
begin
  select * into v_tx from public.transactions where id=p_transaction_id and user_id=p_user_id for update;
  select * into v_event from public.expected_events where id=p_event_id and user_id=p_user_id for update;
  if v_tx.id is null or v_event.id is null then raise exception 'RECORD_NOT_FOUND'; end if;
  if v_tx.status <> 'confirmed' then raise exception 'TRANSACTION_NOT_CONFIRMED'; end if;
  if v_tx.currency_code <> v_event.currency_code then raise exception 'CURRENCY_MISMATCH'; end if;
  if v_tx.type <> (case when v_event.event_type in ('income','expected_income') then 'income' else 'expense' end) then
    raise exception 'TRANSACTION_DIRECTION_MISMATCH';
  end if;
  if v_event.status='fulfilled' and v_event.actual_transaction_id=p_transaction_id then return; end if;
  if v_event.status<>'scheduled' then raise exception 'EVENT_NOT_SCHEDULED'; end if;
  update public.expected_events set status='fulfilled',actual_transaction_id=p_transaction_id where id=p_event_id;
end $$;
revoke all on function public.fulfill_expected_event(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.fulfill_expected_event(uuid,uuid,uuid) to service_role;

create or replace function public.reopen_voided_expectations() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status='voided' and old.status<>'voided' then
    update public.expected_events set status='scheduled',actual_transaction_id=null
      where actual_transaction_id=new.id and user_id=new.user_id;
  end if;
  return new;
end $$;
revoke all on function public.reopen_voided_expectations() from public,anon,authenticated;
drop trigger if exists reopen_voided_expectations on public.transactions;
create trigger reopen_voided_expectations after update of status on public.transactions
  for each row execute function public.reopen_voided_expectations();


-- ======================================================================
-- 20260923000200_account_deletion.sql
-- ======================================================================

-- Durable deletion state and one-use, short-lived reauthentication challenges.
create table if not exists public.account_deletions (
  user_id uuid primary key references auth.users(id) on delete cascade,
  stage text not null default 'files' check(stage in ('files','auth')),
  started_at timestamptz not null default now()
);
create table if not exists public.deletion_challenges (
  token_hash text primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  approved_at timestamptz,
  consumed_at timestamptz
);
create index if not exists deletion_challenges_user_idx on public.deletion_challenges(user_id);
alter table public.account_deletions enable row level security;
alter table public.deletion_challenges enable row level security;
revoke all on public.account_deletions,public.deletion_challenges from public,anon,authenticated;
grant all on public.account_deletions,public.deletion_challenges to service_role;
grant select on public.account_deletions to authenticated;
drop policy if exists deletion_read_own on public.account_deletions;
create policy deletion_read_own on public.account_deletions for select to authenticated using(user_id=(select auth.uid()));

create or replace function public.begin_account_deletion(p_user_id uuid,p_challenge_hash text default null)
returns void language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.profiles where id=p_user_id and status='active' for update;
  if not found then raise exception 'USER_UNAVAILABLE'; end if;
  -- Null is used only after a server-verified password. OAuth must consume a challenge.
  if p_challenge_hash is not null then
    update public.deletion_challenges set consumed_at=now()
      where token_hash=p_challenge_hash and user_id=p_user_id
        and approved_at is not null and consumed_at is null and expires_at>now();
    if not found then raise exception 'REAUTHENTICATION_REQUIRED'; end if;
  end if;
  insert into public.account_deletions(user_id) values(p_user_id) on conflict do nothing;
end $$;
revoke all on function public.begin_account_deletion(uuid,text) from public,anon,authenticated;
grant execute on function public.begin_account_deletion(uuid,text) to service_role;

create or replace function public.reject_writes_during_deletion() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_user uuid;
begin
  v_user := new.user_id;
  perform 1 from public.profiles where id=v_user for share;
  if exists(select 1 from public.account_deletions where user_id=v_user) then
    raise exception 'ACCOUNT_DELETION_IN_PROGRESS';
  end if;
  return new;
end $$;
revoke all on function public.reject_writes_during_deletion() from public,anon,authenticated;
do $$ declare t text; begin
  for t in select table_name from information_schema.columns where table_schema='public' and column_name='user_id'
    and table_name not in ('account_deletions','deletion_challenges')
  loop
    execute format('drop trigger if exists reject_writes_during_deletion on public.%I',t);
    execute format('create trigger reject_writes_during_deletion before insert or update on public.%I for each row execute function public.reject_writes_during_deletion()',t);
  end loop;
end $$;

-- Stop an in-flight upload from creating new files after the deletion sweep.
create or replace function public.reject_storage_during_deletion() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_user uuid; v_prefix text;
begin
  if new.bucket_id <> 'hello-pera-documents' then return new; end if;
  v_prefix := split_part(new.name,'/',1);
  if v_prefix !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return new; end if;
  v_user := v_prefix::uuid;
  perform 1 from public.profiles where id=v_user for share;
  if exists(select 1 from public.account_deletions where user_id=v_user) then raise exception 'ACCOUNT_DELETION_IN_PROGRESS'; end if;
  return new;
end $$;
revoke all on function public.reject_storage_during_deletion() from public,anon,authenticated;
drop trigger if exists reject_storage_during_deletion on storage.objects;
create trigger reject_storage_during_deletion before insert or update on storage.objects
  for each row execute function public.reject_storage_during_deletion();

create or replace function public.erase_deleted_user_audit() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  delete from public.audit_logs where actor_user_id=old.id or target_user_id=old.id;
  delete from public.subscription_events where user_id=old.id;
  insert into public.audit_logs(entity_type,event_type,metadata)
    values('auth','account_deleted','{}'::jsonb);
  return old;
end $$;
revoke all on function public.erase_deleted_user_audit() from public,anon,authenticated;
drop trigger if exists erase_deleted_user_audit on auth.users;
create trigger erase_deleted_user_audit before delete on auth.users
  for each row execute function public.erase_deleted_user_audit();
-- Previously detached deletion records must not retain an email.
update public.audit_logs set metadata='{}'::jsonb,before_data=null,after_data=null,entity_id=null
  where entity_type='auth' and actor_user_id is null and target_user_id is null;


-- ======================================================================
-- 20260923000300_export_snapshot.sql
-- ======================================================================

-- One MVCC snapshot for every export section; authenticated RLS scopes all reads.
create or replace function public.export_financial_snapshot() returns jsonb
language sql stable security invoker set search_path='' as $$
select jsonb_build_object(
  'accounts', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, name, type, nature, currency_code, opening_balance::text as opening_balance, current_balance::text as current_balance, institution_name, is_active, is_archived, created_at from public.accounts) r),
  'categories', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, name, type, is_system, is_active, created_at from public.categories) r),
  'transactions', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, type, direction, amount::text as amount, currency_code, transaction_date, source_account_id, destination_account_id, category_id, merchant_name, description, notes, status, void_reason, created_at from public.transactions) r),
  'bills', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, provider_name, description, category_id, amount::text as amount, currency_code, due_date, status, notes, created_at from public.bills) r),
  'receivables', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, party_name, description, amount::text as amount, currency_code, due_date, status, notes, created_at from public.receivables) r),
  'expected_income', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, source_name, description, category_id, amount::text as amount, currency_code, expected_date, status, notes, created_at from public.expected_income) r),
  'recurring_rules', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, rule_type, name, description, amount::text as amount, currency_code, frequency, interval_count, day_of_month, day_of_week, start_date, end_date, is_active, is_paused, created_at from public.recurring_rules) r),
  'documents', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, document_type, original_filename, original_mime_type, original_size_bytes, processing_status, retention_status, created_at from public.documents) r),
  'bill_payments', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, bill_id, transaction_id, amount_applied::text as amount_applied, created_at from public.bill_payments) r),
  'receivable_payments', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, receivable_id, transaction_id, amount_applied::text as amount_applied, created_at from public.receivable_payments) r),
  'expected_income_receipts', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, expected_income_id, transaction_id, amount_applied::text as amount_applied, created_at from public.expected_income_receipts) r),
  'expected_events', (select coalesce(jsonb_agg(r order by r.id),'[]'::jsonb) from (select id, recurring_rule_id, event_type, name, amount::text as amount, currency_code, scheduled_date, status, account_id, category_id, actual_transaction_id, include_in_forecast, detached_from_rule, source_entity_type, source_entity_id, created_at from public.expected_events) r)
) where auth.uid() is not null;
$$;
revoke all on function public.export_financial_snapshot() from public,anon;
grant execute on function public.export_financial_snapshot() to authenticated;

-- Complete obligation totals, including more than 1,000 allocation links.
create or replace function public.read_obligations(
  p_kind text, p_archived boolean default false, p_open boolean default false,
  p_from date default null, p_to date default null, p_id uuid default null,
  p_offset integer default 0, p_limit integer default null
) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare t text; links text; fk text; date_col text; result jsonb;
begin
  case p_kind
    when 'bill' then t:='bills'; links:='bill_payments'; fk:='bill_id'; date_col:='due_date';
    when 'receivable' then t:='receivables'; links:='receivable_payments'; fk:='receivable_id'; date_col:='due_date';
    when 'expected_income' then t:='expected_income'; links:='expected_income_receipts'; fk:='expected_income_id'; date_col:='expected_date';
    else raise exception 'UNKNOWN_OBLIGATION_TYPE';
  end case;
  execute format('select coalesce(jsonb_agg(to_jsonb(o) || jsonb_build_object(''amount'',o.amount::text,%L,
    jsonb_build_array(jsonb_build_object(''amount_applied'',(select coalesce(sum(l.amount_applied),0)::text from public.%I l where l.%I=o.id))))
    order by o.%I,o.id),''[]''::jsonb) from (select * from public.%I
    where ($1 or not is_archived) and (not $2 or status in (''open'',''partially_paid''))
    and ($3 is null or %I >= $3) and ($4 is null or %I <= $4) and ($5 is null or id=$5)
    order by %I,id limit $7 offset $6) o',links,links,fk,date_col,t,date_col,date_col,date_col)
    into result using p_archived,p_open,p_from,p_to,p_id,p_offset,p_limit;
  return result;
end $$;
revoke all on function public.read_obligations(text,boolean,boolean,date,date,uuid,integer,integer) from public,anon;
grant execute on function public.read_obligations(text,boolean,boolean,date,date,uuid,integer,integer) to authenticated;
